export async function generateLeagueSchedule(instanceId?: string) {
  try {
    if (!instanceId) return { success: false, error: 'instanceId is required.' };

    // 1. Get all 14 teams for this instance
    const { data: standings } = await supabaseAdmin
      .from('league_standings')
      .select('team_id')
      .eq('league_instance_id', instanceId);

    if (!standings || standings.length !== 14) {
      return { success: false, error: `Must have exactly 14 teams in standings to generate a full schedule. Found: ${standings?.length}` };
    }

    const teamIds = standings.map(s => s.team_id);
    const matchesToInsert = [];

    // Round-robin algorithm for 14 teams
    const numTeams = 14;
    const numRounds = 13;
    const halfSize = numTeams / 2;

    let teams = [...teamIds];

    for (let round = 1; round <= numRounds; round++) {
      for (let i = 0; i < halfSize; i++) {
        const home = teams[i];
        const away = teams[numTeams - 1 - i];

        let matchHome = home;
        let matchAway = away;

        if (round % 2 === 0 && i === 0) {
          matchHome = away;
          matchAway = home;
        }

        // 1st leg
        matchesToInsert.push({ league_instance_id: instanceId, round_number: round, home_team_id: matchHome, away_team_id: matchAway, is_played: false });

        // 2nd leg (reverse fixture, +13 rounds)
        matchesToInsert.push({ league_instance_id: instanceId, round_number: round + 13, home_team_id: matchAway, away_team_id: matchHome, is_played: false });
      }

      const firstTeam = teams[0];
      const secondTeam = teams[1];
      teams.splice(1, 1);
      teams.push(secondTeam);
    }

    const { error } = await supabaseAdmin.from('league_matches').insert(matchesToInsert);
    if (error) {
      console.error("League Generation Error:", error);
      throw error;
    }

    return { success: true, message: `Successfully generated ${matchesToInsert.length} matches across 26 rounds for instance ${instanceId}.` };
  } catch (err: any) {
    return { success: false, error: err.message || 'Unknown error during schedule generation.' };
  }
}

export async function simulateNextRound(userId?: string) {
  try {
    let userTeamId = null;
    if (userId) {
      const { data: ut } = await supabaseAdmin.from('teams').select('id').eq('user_id', userId).single();
      if (ut) userTeamId = ut.id;
    }

    // Find lowest round_number where is_played == false
    const { data: unplayedMatches } = await supabaseAdmin
      .from('league_matches')
      .select('round_number')
      .eq('is_played', false)
      .order('round_number', { ascending: true })
      .limit(1);

    if (!unplayedMatches || unplayedMatches.length === 0) {
      return { success: false, error: 'No unplayed rounds left in the schedule.' };
    }

    const targetRound = unplayedMatches[0].round_number;

    // Get all matches for this round
    const { data: matches } = await supabaseAdmin
      .from('league_matches')
      .select('*')
      .eq('round_number', targetRound)
      .eq('is_played', false);

    if (!matches || matches.length === 0) return { success: false, error: 'No matches found for the target round.' };

    const updates = [];
    const teamStats: Record<string, { matches: number, wins: number, draws: number, losses: number, gf: number, ga: number, pts: number }> = {};

    // Fetch user IDs and names for fancoins distribution and reports
    const { data: teamsData } = await supabaseAdmin.from('teams').select('id, user_id, name');
    const teamUsers: Record<string, string> = {};
    const teamNames: Record<string, string> = {};
    if (teamsData) {
      teamsData.forEach(t => {
        teamUsers[t.id] = t.user_id;
        teamNames[t.id] = t.name;
      });
    }

    // Fetch infrastructure for stadium level
    const { data: infraData } = await supabaseAdmin.from('infrastructure').select('team_id, stadium_level');
    const teamStadiums: Record<string, number> = {};
    if (infraData) {
      infraData.forEach(i => teamStadiums[i.team_id] = i.stadium_level);
    }

    // Initialize stats
    // ── L1 FIX: Scope standings query to this league instance only ────────────
    // Previously fetched ALL standings without a WHERE clause. This caused:
    //   1. Full-table scan — OOM / timeout as the game scales to 1000+ leagues
    //   2. Stats accumulation across different league instances for teams
    //      that played in multiple historical seasons
    //
    // We resolve the league_instance_id from the first match in the batch.
    const leagueInstanceId = matches[0]?.league_instance_id;

    const { data: currentStandings } = await supabaseAdmin
      .from('league_standings')
      .select('*')
      .eq('league_instance_id', leagueInstanceId);

    if (currentStandings) {
      currentStandings.forEach(s => {
        teamStats[s.team_id] = {
          matches: s.matches_played || 0,
          wins: s.wins || 0,
          draws: s.draws || 0,
          losses: s.losses || 0,
          gf: s.goals_for || 0,
          ga: s.goals_against || 0,
          pts: s.points || 0
        };
      });
    }

    const matchReports = []; // Array to collect reports
    const playerUpdates: Record<string, any> = {}; // Track player state changes

    // Fetch players for all teams in the target round
    const teamIdsInRound = matches.flatMap(m => [m.home_team_id, m.away_team_id]);
    const { data: roundPlayers } = await supabaseAdmin
      .from('players')
      .select('id, team_id, name, position, ovr, lineup_slot, lineup_status, is_injured, stamina')
      .in('team_id', teamIdsInRound)
      .eq('lineup_status', 'starting')
      .eq('is_injured', false);

    const playersByTeam: Record<string, any[]> = {};
    teamIdsInRound.forEach(id => playersByTeam[id] = []);
    if (roundPlayers) {
      roundPlayers.forEach(p => {
        if (playersByTeam[p.team_id]) playersByTeam[p.team_id].push(p);

        // Stamina Decay (15 to 25 points)
        const decay = Math.floor(Math.random() * 11) + 15;
        const newStamina = Math.max(0, p.stamina - decay);
        playerUpdates[p.id] = { ...playerUpdates[p.id], stamina: newStamina };
      });
    }

    // Fetch injured players to process natural healing
    const { data: injuredPlayers } = await supabaseAdmin
      .from('players')
      .select('id, injury_matches_left')
      .in('team_id', teamIdsInRound)
      .eq('is_injured', true);

    if (injuredPlayers) {
      injuredPlayers.forEach(p => {
        const newLeft = (p.injury_matches_left || 1) - 1;
        if (newLeft <= 0) {
          playerUpdates[p.id] = { ...playerUpdates[p.id], is_injured: false, injury_matches_left: 0 };
        } else {
          playerUpdates[p.id] = { ...playerUpdates[p.id], injury_matches_left: newLeft };
        }
      });
    }

    for (const match of matches) {
      let homeOvr = playersByTeam[match.home_team_id].reduce((sum, p) => sum + p.ovr, 0) / Math.max(1, playersByTeam[match.home_team_id].length) || 50;
      let awayOvr = playersByTeam[match.away_team_id].reduce((sum, p) => sum + p.ovr, 0) / Math.max(1, playersByTeam[match.away_team_id].length) || 50;

      const events: any[] = [];
      let homeRedCards = 0;
      let awayRedCards = 0;

      // Cards Generation
      if (Math.random() < 0.3) {
        const isHome = Math.random() > 0.5;
        const teamId = isHome ? match.home_team_id : match.away_team_id;
        const teamPlayers = playersByTeam[teamId];
        if (teamPlayers.length > 0) {
          const player = teamPlayers[Math.floor(Math.random() * teamPlayers.length)];
          const isRed = Math.random() < (0.05 / 0.30); // 5% overall chance
          events.push({
            type: isRed ? 'red_card' : 'yellow_card',
            player_id: player.id,
            player_name: player.name,
            team_id: teamId,
            minute: Math.floor(Math.random() * 90) + 1
          });
          if (isRed) {
            if (isHome) { homeRedCards++; homeOvr *= 0.9; }
            else { awayRedCards++; awayOvr *= 0.9; }
          }
        }
      }

      // Injuries Generation (10% chance per match)
      if (Math.random() < 0.1) {
        const isHome = Math.random() > 0.5;
        const teamId = isHome ? match.home_team_id : match.away_team_id;
        const teamPlayers = playersByTeam[teamId];
        if (teamPlayers.length > 0) {
          const player = teamPlayers[Math.floor(Math.random() * teamPlayers.length)];
          events.push({
            type: 'injury',
            player_id: player.id,
            player_name: player.name,
            team_id: teamId,
            minute: Math.floor(Math.random() * 90) + 1
          });
          const injuryMatches = Math.floor(Math.random() * 3) + 1;
          playerUpdates[player.id] = { ...playerUpdates[player.id], is_injured: true, injury_matches_left: injuryMatches };
        }
      }

      // Score Generation based on OVR difference
      const ovrDiff = homeOvr - awayOvr;
      const baseGoals = 1.5;
      let homeExpected = baseGoals + (ovrDiff * 0.1);
      let awayExpected = baseGoals - (ovrDiff * 0.1);

      let homeScore = Math.max(0, Math.floor(homeExpected + (Math.random() * 3 - 1.5)));
      let awayScore = Math.max(0, Math.floor(awayExpected + (Math.random() * 3 - 1.5)));

      // Goals Generation
      const generateGoals = (score: number, teamId: string) => {
        const teamPlayers = playersByTeam[teamId];
        const attackers = teamPlayers.filter(p => ['FWD', 'MID', 'LWF', 'RWF', 'ST', 'CF', 'CAM'].includes(p.position || p.lineup_slot?.split('_')[0]));
        const available = attackers.length > 0 ? attackers : teamPlayers;

        for (let i = 0; i < score; i++) {
          if (available.length > 0) {
            const player = available[Math.floor(Math.random() * available.length)];
            events.push({
              type: 'goal',
              player_id: player.id,
              player_name: player.name,
              team_id: teamId,
              minute: Math.floor(Math.random() * 90) + 1
            });
          }
        }
      };

      generateGoals(homeScore, match.home_team_id);
      generateGoals(awayScore, match.away_team_id);

      // Knockout & Penalty Logic
      let penaltyEvent = null;
      if (match.is_knockout && homeScore === awayScore) {
        const homePen = Math.floor(Math.random() * 2) + 4; // 4 or 5
        const awayPen = homePen === 5 ? Math.floor(Math.random() * 2) + 3 : 5; // e.g. 5:4 or 4:5

        penaltyEvent = {
          type: 'penalty_shootout',
          score: `${homePen}:${awayPen}`,
          winner_team_id: homePen > awayPen ? match.home_team_id : match.away_team_id
        };
        events.push(penaltyEvent);
      }

      // Sort events by minute
      events.sort((a, b) => (a.minute || 0) - (b.minute || 0));

      matchReports.push({
        match_id: match.id,
        home_team_id: match.home_team_id,
        home_team_name: teamNames[match.home_team_id] || 'Unknown Home Team',
        away_team_id: match.away_team_id,
        away_team_name: teamNames[match.away_team_id] || 'Unknown Away Team',
        home_score: homeScore,
        away_score: awayScore,
        is_knockout: match.is_knockout,
        events
      });

      // Queue match update
      updates.push(supabaseAdmin.from('league_matches').update({
        home_score: homeScore,
        away_score: awayScore,
        is_played: true,
        match_events: events
      }).eq('id', match.id));

      // Update team stats safely
      if (!teamStats[match.home_team_id]) teamStats[match.home_team_id] = { matches: 0, wins: 0, draws: 0, losses: 0, gf: 0, ga: 0, pts: 0 };
      if (!teamStats[match.away_team_id]) teamStats[match.away_team_id] = { matches: 0, wins: 0, draws: 0, losses: 0, gf: 0, ga: 0, pts: 0 };

      const h = teamStats[match.home_team_id];
      const a = teamStats[match.away_team_id];

      h.matches++;
      a.matches++;
      h.gf += homeScore;
      h.ga += awayScore;
      a.gf += awayScore;
      a.ga += homeScore;

      if (homeScore > awayScore) {
        h.wins++; h.pts += 3;
        a.losses++;
      } else if (homeScore < awayScore) {
        a.wins++; a.pts += 3;
        h.losses++;
      } else {
        h.draws++; h.pts += 1;
        a.draws++; a.pts += 1;
      }

      // Fancoins Economy
      let homeAmount = 50 * (teamStadiums[match.home_team_id] || 1); // home bonus tickets
      let awayAmount = 0;
      if (homeScore > awayScore) {
        homeAmount += 100;
        awayAmount += 10;
      } else if (homeScore < awayScore) {
        awayAmount += 100;
        homeAmount += 10;
      } else {
        homeAmount += 50;
        awayAmount += 50;
      }

      if (teamUsers[match.home_team_id]) {
        updates.push(supabaseAdmin.rpc('increment_fancoins', { u_id: teamUsers[match.home_team_id], amount: homeAmount }));
      }
      if (teamUsers[match.away_team_id]) {
        updates.push(supabaseAdmin.rpc('increment_fancoins', { u_id: teamUsers[match.away_team_id], amount: awayAmount }));
      }
    }
    // Await match and fancoins updates
    await Promise.all(updates);

    // Process all accumulated player updates with explicit error logging
    const playerUpdatePromises = Object.keys(playerUpdates).map(async (playerId) => {
      const payload = playerUpdates[playerId];
      // Safety check for stamina
      if (payload.stamina !== undefined && payload.stamina < 0) {
        payload.stamina = 0;
      }

      const { error } = await supabaseAdmin
        .from('players')
        .update(payload)
        .eq('id', playerId);

      if (error) {
        console.error(`[MatchEngine] Failed to update player ${playerId}:`, error);
      }
    });

    await Promise.all(playerUpdatePromises);

    // Batch update standings
    // ── L1/L3 FIX: Scope each UPDATE to the correct league_instance_id ────────
    // leagueInstanceId was resolved from matches[0] above (see standings SELECT fix).
    // Without this, a team promoted/relegated into multiple historical instances
    // would have ALL its rows updated simultaneously — corrupting past season data.
    const standingsUpdates = Object.entries(teamStats).map(([teamId, st]) =>
      supabaseAdmin.from('league_standings').update({
        matches_played: st.matches,
        wins:           st.wins,
        draws:          st.draws,
        losses:         st.losses,
        goals_for:      st.gf,
        goals_against:  st.ga,
        points:         st.pts
      })
        .eq('team_id', teamId)
        .eq('league_instance_id', leagueInstanceId)  // L3 FIX: scope to active instance
    );

    await Promise.all(standingsUpdates);

    // Revalidate Next.js cache to ensure UI gets fresh data
    revalidatePath('/lineup');
    revalidatePath('/base');

    return { 
      success: true, 
      message: `Simulated Round ${targetRound} successfully. ${matches.length} matches played.`, 
      matchReports,
      userTeamId,
      userMatchReport: userTeamId ? matchReports.find(r => r.home_team_id === userTeamId || r.away_team_id === userTeamId) : null
    };
  } catch (err: any) {
    return { success: false, error: err.message || 'Unknown error during simulation.' };
  }
}

'use server';

import { supabase } from '@/lib/supabase';
import { revalidatePath } from 'next/cache';
import { cookies } from 'next/headers';

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

export type ManagerProfileType = 'runner' | 'lifter' | 'yogi' | 'ball_player';
export type CurrencyType = 'cardio' | 'fitness' | 'ball' | 'strength';

export interface SyncStepsResult {
  added_steps: number;
  sp_gained: number;
  total_sp: number;
  daily_steps: number;
}

export interface ConvertSpResult {
  sp_spent: number;
  gained_coins: number;
  currency: CurrencyType;
  multiplier: number;
  new_balance_sp: number;
  new_balance_currency: number;
}

export interface ActionResponse<T> {
  success: boolean;
  data?: T;
  error?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Helper: Get authenticated user ID from session cookie
// ─────────────────────────────────────────────────────────────────────────────

async function getAuthenticatedUserId(): Promise<string | null> {
  const cookieStore = await cookies();
  return cookieStore.get('tg_user_id')?.value ?? null;
}

// ─────────────────────────────────────────────────────────────────────────────
// ACTION: syncStepsAction
//
// Calls the DB RPC `sync_daily_steps` which:
//   - Enforces a 25,000 steps/day hard cap
//   - Uses FLOOR math to prevent fractional SP accumulation
//   - Atomically credits Sweat Points with FOR UPDATE row locking
//
// Usage: call from fitness sync endpoints or training page.
// ─────────────────────────────────────────────────────────────────────────────

export async function syncStepsAction(
  stepsToAdd: number
): Promise<ActionResponse<SyncStepsResult>> {
  try {
    const userId = await getAuthenticatedUserId();
    if (!userId) {
      return { success: false, error: 'Unauthorized: Valid Telegram session required.' };
    }

    if (!Number.isInteger(stepsToAdd) || stepsToAdd < 0) {
      return { success: false, error: 'Invalid steps value: must be a non-negative integer.' };
    }

    const { data, error } = await supabase.rpc('sync_daily_steps', {
      p_user_id:      userId,
      p_steps_to_add: stepsToAdd,
    });

    if (error) {
      console.error('[syncStepsAction] RPC Error:', error);
      return { success: false, error: error.message ?? 'Failed to sync steps.' };
    }

    // Supabase returns the JSONB result as a parsed JS object
    const result = data as SyncStepsResult;

    // Invalidate all pages that may display step / SP balance
    revalidatePath('/');
    revalidatePath('/training');
    revalidatePath('/profile');

    return { success: true, data: result };

  } catch (err: any) {
    console.error('[syncStepsAction] Unexpected error:', err);
    return { success: false, error: err.message ?? 'An unexpected error occurred.' };
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// ACTION: convertSweatPointsAction
//
// Calls the DB RPC `convert_sp_to_currency` which:
//   - Locks the user row FOR UPDATE before any reads/writes
//   - Verifies the user has sufficient SP balance
//   - Applies the asymmetric multiplier matrix based on manager_profile:
//
//     Profile      | cardio | fitness | ball | strength
//     -------------|--------|---------|------|---------
//     runner       |  1.0   |  0.6    | 0.4  |  0.2
//     yogi         |  0.6   |  1.0    | 0.4  |  0.2
//     ball_player  |  0.2   |  0.6    | 1.0  |  0.4
//     lifter       |  0.2   |  0.4    | 0.6  |  1.0
//
//   - FLOORs the result to prevent fractional coin exploitation
//   - Atomically debits SP and credits the requested coin column
//
// Usage: call from Sweat Bank exchange UI.
// ─────────────────────────────────────────────────────────────────────────────

export async function convertSweatPointsAction(
  currencyType: CurrencyType,
  spAmount: number
): Promise<ActionResponse<ConvertSpResult>> {
  try {
    const userId = await getAuthenticatedUserId();
    if (!userId) {
      return { success: false, error: 'Unauthorized: Valid Telegram session required.' };
    }

    const validCurrencies: CurrencyType[] = ['cardio', 'fitness', 'ball', 'strength'];
    if (!validCurrencies.includes(currencyType)) {
      return { success: false, error: `Invalid currency type: "${currencyType}". Must be one of: ${validCurrencies.join(', ')}.` };
    }

    if (!Number.isInteger(spAmount) || spAmount <= 0) {
      return { success: false, error: 'sp_amount must be a positive integer.' };
    }

    const { data, error } = await supabase.rpc('convert_sp_to_currency', {
      p_user_id:  userId,
      p_currency: currencyType,
      p_sp_amount: spAmount,
    });

    if (error) {
      console.error('[convertSweatPointsAction] RPC Error:', error);
      // Expose user-friendly message for balance errors from the DB
      const msg = error.message?.includes('Insufficient')
        ? 'Not enough Sweat Points to complete this exchange.'
        : (error.message ?? 'Conversion failed.');
      return { success: false, error: msg };
    }

    const result = data as ConvertSpResult;

    // Invalidate any page that shows wallet / coin balances
    revalidatePath('/');
    revalidatePath('/profile');

    return { success: true, data: result };

  } catch (err: any) {
    console.error('[convertSweatPointsAction] Unexpected error:', err);
    return { success: false, error: err.message ?? 'An unexpected error occurred.' };
  }
}

'use server';

import { supabase } from '@/lib/supabase';
import { cookies } from 'next/headers';
import { revalidatePath } from 'next/cache';

export async function swapPlayers(playerOutId: string, playerInId: string) {
  try {
    const cookieStore = await cookies();
    const tgUserId = cookieStore.get('tg_user_id')?.value;

    if (!tgUserId) {
      return { success: false, error: 'Unauthorized: Valid Telegram session required.' };
    }

    if (!playerOutId || !playerInId) {
      return { success: false, error: 'Missing required parameters' };
    }

    // 1. Verify user's team
    const { data: team, error: teamError } = await supabase
      .from('teams')
      .select('id, is_ready_for_match')
      .eq('user_id', tgUserId)
      .single();

    if (teamError || !team) {
      return { success: false, error: 'Team not found' };
    }

    // 2. Fetch both players to verify ownership and current status
    const { data: players, error: playersError } = await supabase
      .from('players')
      .select('id, team_id, lineup_status, lineup_slot, position')
      .in('id', [playerOutId, playerInId]);

    if (playersError || !players || players.length !== 2) {
      return { success: false, error: 'Players not found or invalid selection' };
    }

    // Check ownership
    if (players[0].team_id !== team.id || players[1].team_id !== team.id) {
      return { success: false, error: 'Players do not belong to your franchise' };
    }

    const playerOut = players.find(p => p.id === playerOutId);
    const playerIn = players.find(p => p.id === playerInId);

    if (!playerOut || !playerIn) {
      return { success: false, error: 'Invalid player IDs' };
    }

    const tempSlot = playerOut.lineup_slot || null;
    const tempStatus = playerOut.lineup_status;

    // 3. Perform the swap via two updates
    // We swap both `lineup_status` and `lineup_slot`
    const { error: update1Error } = await supabase
      .from('players')
      .update({ 
        lineup_status: playerIn.lineup_status,
        lineup_slot: playerIn.lineup_slot || null
      })
      .eq('id', playerOut.id);

    const { error: update2Error } = await supabase
      .from('players')
      .update({ 
        lineup_status: tempStatus,
        lineup_slot: tempSlot
      })
      .eq('id', playerIn.id);

    if (update1Error || update2Error) {
      return { success: false, error: 'Failed to execute swap in database' };
    }

    revalidatePath('/lineup');
    return { success: true, message: 'Swap successful' };

  } catch (error: any) {
    console.error("Lineup Swap Action Error:", error);
    return { success: false, error: error.message || 'Internal Server Error' };
  }
}

export async function updatePlayers(payload: { id: string; lineup_status: string; lineup_slot: string | null }[]) {
  try {
    const cookieStore = await cookies();
    const tgUserId = cookieStore.get('tg_user_id')?.value;

    if (!tgUserId) {
      return { success: false, error: 'Unauthorized' };
    }

    // 1. Verify user's team
    const { data: team, error: teamError } = await supabase
      .from('teams')
      .select('id')
      .eq('user_id', tgUserId)
      .single();

    if (teamError || !team) {
      return { success: false, error: 'Team not found' };
    }

    console.log('Sending payload to Supabase:', JSON.stringify(payload, null, 2));

    const updatePromises = payload.map(p => 
      supabase
        .from('players')
        .update({
          lineup_status: p.lineup_status,
          lineup_slot: p.lineup_slot !== null && p.lineup_slot !== undefined ? String(p.lineup_slot) : null
        })
        .eq('id', p.id)
        .eq('team_id', team.id)
    );

    const results = await Promise.all(updatePromises);

    // Check for any errors in the batch
    const errors = results.filter(r => r.error).map(r => r.error);
    if (errors.length > 0) {
      console.error("Supabase bulk update errors:", errors);
      throw new Error(`Database error: Failed to update ${errors.length} players. First error: ${errors[0]?.message}`);
    }

    revalidatePath('/lineup');
    return { success: true };
  } catch (err: any) {
    console.error("updatePlayers Action Error:", err);
    return { success: false, error: err.message };
  }
}

export async function updateTeamFormation(teamId: string, formation: string) {
  try {
    const cookieStore = await cookies();
    const tgUserId = cookieStore.get('tg_user_id')?.value;

    if (!tgUserId) {
      return { success: false, error: 'Unauthorized: Valid Telegram session required.' };
    }

    // 1. Verify user's team ownership
    const { data: teamAuth, error: teamAuthError } = await supabase
      .from('teams')
      .select('id')
      .eq('id', teamId)
      .eq('user_id', tgUserId)
      .single();

    if (teamAuthError || !teamAuth) {
      return { success: false, error: 'Forbidden: You do not own this team.' };
    }

    // 2. Update Formation
    const allowedFormations = ['4-4-2', '4-3-3', '3-5-2'];
    if (!allowedFormations.includes(formation)) {
      return { success: false, error: 'Invalid formation' };
    }

    const { error: updateError } = await supabase
      .from('teams')
      .update({ formation })
      .eq('id', teamId);

    if (updateError) {
      throw updateError;
    }

    revalidatePath('/lineup');
    return { success: true };
  } catch (error: any) {
    console.error('Update team formation failed:', error);
    return { success: false, error: error.message || 'An unexpected error occurred.' };
  }
}

