    return NextResponse.json({ error: 'Internal Server Error', details: error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function POST(req: Request) {
  try {
    const { userId, playerOutId, playerInId } = await req.json();

    if (!userId || !playerOutId || !playerInId) {
      return NextResponse.json({ error: 'Missing required parameters' }, { status: 400 });
    }

    // 1. Verify user's team
    const { data: team, error: teamError } = await supabase
      .from('teams')
      .select('id, is_ready_for_match')
      .eq('user_id', userId)
      .single();

    if (teamError || !team) {
      return NextResponse.json({ error: 'Team not found' }, { status: 404 });
    }

    if (team.is_ready_for_match) {
      return NextResponse.json({ error: 'Cannot swap players while lineup is locked for a match' }, { status: 400 });
    }

    // 2. Fetch both players to verify ownership and current status
    const { data: players, error: playersError } = await supabase
      .from('players')
      .select('id, team_id, lineup_status, position')
      .in('id', [playerOutId, playerInId]);

    if (playersError || !players || players.length !== 2) {
      return NextResponse.json({ error: 'Players not found or invalid selection' }, { status: 404 });
    }

    // Check ownership
    if (players[0].team_id !== team.id || players[1].team_id !== team.id) {
      return NextResponse.json({ error: 'Players do not belong to your franchise' }, { status: 403 });
    }

    const playerOut = players.find(p => p.id === playerOutId);
    const playerIn = players.find(p => p.id === playerInId);

    if (!playerOut || !playerIn) {
      return NextResponse.json({ error: 'Invalid player IDs' }, { status: 400 });
    }

    // Basic constraint: One must be starting, one must be bench
    if (playerOut.lineup_status === playerIn.lineup_status) {
      return NextResponse.json({ error: 'Players must have different lineup statuses to swap' }, { status: 400 });
    }

    // (Optional) Enforce strict positional swapping. For MVP, we can let users swap any position, 
    // but the prompt says: "handle edge cases gracefully (e.g. prevent swapping GK for FWD if you want strict positional logic...)"
    // Let's enforce strict position matching for simplicity so formation remains strictly 4-4-2.
    if (playerOut.position !== playerIn.position) {
      return NextResponse.json({ error: `Cannot swap a ${playerOut.position} with a ${playerIn.position}. Positions must match.` }, { status: 400 });
    }

    // 3. Perform the swap via two updates (for MVP without RPC)
    const { error: update1Error } = await supabase
      .from('players')
      .update({ lineup_status: playerIn.lineup_status })
      .eq('id', playerOut.id);

    const { error: update2Error } = await supabase
      .from('players')
      .update({ lineup_status: playerOut.lineup_status })
      .eq('id', playerIn.id);

    if (update1Error || update2Error) {
      return NextResponse.json({ error: 'Failed to execute swap in database' }, { status: 500 });
    }

    return NextResponse.json({ success: true, message: 'Swap successful' });

  } catch (error: any) {
    console.error("Lineup Swap API Error:", error);
    return NextResponse.json({ error: 'Internal Server Error', details: error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function GET() {
  try {
    const { data: listings, error } = await supabase
      .from('transfer_market')
      .select(`
        id,
        price_ton,
        created_at,
        seller_id,
        players (
          id,
          name,
          age,
          ovr,
          perks
        )
      `)
      .eq('is_active', true)
      .order('created_at', { ascending: false });

    if (error) {
      throw new Error(`Failed to fetch active market listings: ${error.message}`);
    }

    // Map the Supabase relationship response into a cleaner structure for the UI
    const formattedListings = (listings || []).map(item => {
      // Supabase relationships return an object if 1:1, or array for 1:N. Our schema is N:1 from market to players, so it's generally an object.
      const playerObj = Array.isArray(item.players) ? item.players[0] : item.players;
      return {
        id: item.id,
        price_ton: item.price_ton,
        created_at: item.created_at,
        seller_id: item.seller_id,
        player: playerObj,
      };
    }).filter(item => item.player); // Defensively filter anomalies

    return NextResponse.json({
      success: true,
      listings: formattedListings,
    });
  } catch (error: any) {
    console.error("Active Market API Error:", error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export interface MarketListRequest {
  userId: string;
  playerId: string;
  priceTon: number;
}

const LISTING_FEE_FANCOINS = 100;

export async function POST(req: Request) {
  try {
    const body: Partial<MarketListRequest> = await req.json();
    const { userId, playerId, priceTon } = body;

    // 1. Payload Verification
    if (!userId || !playerId || priceTon === undefined || priceTon <= 0) {
      return NextResponse.json(
        { error: 'Missing or invalid payload fields: userId, playerId, or priceTon' },
        { status: 400 }
      );
    }

    // 2. Verify Player Ownership
    // Extract the team_id for the player
    const { data: playerData, error: playerError } = await supabase
      .from('players')
      .select('id, team_id')
      .eq('id', playerId)
      .single();

    if (playerError || !playerData) {
      return NextResponse.json(
        { error: 'Player not found or database read error' },
        { status: 404 }
      );
    }

    // Verify the team belongs to the requesting user
    const { data: teamData, error: teamError } = await supabase
      .from('teams')
      .select('user_id')
      .eq('id', playerData.team_id)
      .single();

    if (teamError || !teamData || teamData.user_id !== userId) {
      return NextResponse.json(
        { error: 'Forbidden: You do not own the team this player belongs to' },
        { status: 403 }
      );
    }

    // 3. Spam Defense: Check for existing active listing
    const { data: existingListing } = await supabase
      .from('transfer_market')
      .select('id')
      .eq('player_id', playerId)
      .eq('is_active', true)
      .single();

    if (existingListing) {
      return NextResponse.json(
        { error: 'Conflict: This player is already listed actively on the market' },
        { status: 409 }
      );
    }

    // 4. Economic Verification & Burn (Simulated Transaction)
    // Fetch user FanCoin balance
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('balance_fancoins')
      .eq('id', userId)
      .single();

    if (userError || !user) {
      return NextResponse.json(
        { error: 'User not found during economic validation' },
        { status: 404 }
      );
    }

    const currentBalance = Number(user.balance_fancoins) || 0;

    if (currentBalance < LISTING_FEE_FANCOINS) {
      return NextResponse.json(
        { error: `Insufficient FanCoins. Required: ${LISTING_FEE_FANCOINS}, Balance: ${currentBalance}` },
        { status: 400 }
      );
    }

    const newBalance = currentBalance - LISTING_FEE_FANCOINS;

    // Deduct coins preemptively (if market insert fails, we refund via catch block)
    const { error: deductError } = await supabase
      .from('users')
      .update({ balance_fancoins: newBalance })
      .eq('id', userId);

    if (deductError) {
      throw new Error(`Failed to deduct FanCoins: ${deductError.message}`);
    }

    // 5. Insert Market Listing
    const { data: marketListing, error: marketError } = await supabase
      .from('transfer_market')
      .insert({
        player_id: playerId,
        seller_id: userId,
        price_ton: priceTon,
        is_active: true,
      })
      .select('id')
      .single();

    if (marketError) {
      // Manual Rollback: Refund FanCoins
      console.error("Market insert failed, initiating rollback...", marketError);
      await supabase
        .from('users')
        .update({ balance_fancoins: currentBalance })
        .eq('id', userId);

      throw new Error(`Failed to create market listing: ${marketError.message}. FanCoins successfully refunded.`);
    }

    // 6. Return Success
    return NextResponse.json({
      success: true,
      listing_id: marketListing.id,
      new_balance_fancoins: newBalance,
    });

  } catch (error: any) {
    console.error("Market Listing API Error:", error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function GET() {
  try {
    // 1. Fetch latest 10 matches
    const { data: matches, error: matchError } = await supabase
      .from('league_matches')
      .select('id, home_team_id, away_team_id, home_score, away_score, created_at')
      .eq('status', 'completed')
      .order('created_at', { ascending: false })
      .limit(10);

    if (matchError) {
      throw new Error(`Failed to fetch matches: ${matchError.message}`);
    }

    if (!matches || matches.length === 0) {
      return NextResponse.json({ success: true, matches: [] });
    }

    // 2. Fetch corresponding team names efficiently
    const teamIds = [...new Set(matches.flatMap(m => [m.home_team_id, m.away_team_id]))];
    const { data: teams, error: teamsError } = await supabase
      .from('teams')
      .select('id, name')
      .in('id', teamIds);

    if (teamsError) {
      throw new Error(`Failed to fetch team names for journal mapping: ${teamsError.message}`);
    }

    // Create a dictionary for quick lookup
    const teamMap: Record<string, string> = {};
    if (teams) {
      teams.forEach(t => teamMap[t.id] = t.name);
    }

    // 3. Map into the final enriched payload
    const enrichedMatches = matches.map(m => ({
      id: m.id,
      home_score: m.home_score,
      away_score: m.away_score,
      match_date: (m as any).created_at,
      home_team_name: teamMap[m.home_team_id] || 'Unknown Home',
      away_team_name: teamMap[m.away_team_id] || 'Unknown Away',
