'use client';

import React, { createContext, useState, ReactNode, useEffect } from 'react';

type Language = 'en' | 'ru';

interface LanguageContextType {
  language: Language;
  setLanguage: (lang: Language) => void;
}

export const LanguageContext = createContext<LanguageContextType>({
  language: 'en',
  setLanguage: () => {},
});

export const LanguageProvider = ({ children }: { children: ReactNode }) => {
  const [language, setLanguageState] = useState<Language>('en');

  useEffect(() => {
    const initLanguage = async () => {
      try {
        const saved = localStorage.getItem('fitmanager_lang');
        if (saved === 'ru' || saved === 'en') {
          setLanguageState(saved);
        } else {
          const module = await import('@twa-dev/sdk');
          const WebApp = module.default;
          const twaLang = WebApp.initDataUnsafe?.user?.language_code;
          if (twaLang === 'ru') {
            setLanguageState('ru');
          } else {
            setLanguageState('en');
          }
        }
      } catch (e) {
        console.warn('LanguageContext init error', e);
      }
    };
    initLanguage();
  }, []);

  const setLanguage = (lang: Language) => {
    setLanguageState(lang);
    localStorage.setItem('fitmanager_lang', lang);
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage }}>
      {children}
    </LanguageContext.Provider>
  );
};

'use client';

import { useEffect, useState } from 'react';
import { getMatchHistory, getMatchSchedule } from '@/app/actions/matchActions';
import { MatchReport, MatchReportModal } from '@/components/MatchReportModal';
import { BookOpen, CalendarDays } from 'lucide-react';

import { dict } from '@/lib/dictionaries';

export function MatchHistoryWidget({ userId, teamName, language = 'en' }: { userId: string; teamName: string | null; language?: string }) {
  const t = dict[language as keyof typeof dict];
  const [history, setHistory] = useState<MatchReport[]>([]);
  const [schedule, setSchedule] = useState<MatchReport[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedReport, setSelectedReport] = useState<MatchReport | null>(null);
  const [userTeamId, setUserTeamId] = useState<string>('');
  const [viewMode, setViewMode] = useState<'journal' | 'schedule'>('journal');

  useEffect(() => {
    let mounted = true;

    const fetchMatches = async () => {
      setIsLoading(true);
      try {
        const [histRes, schedRes] = await Promise.all([
          getMatchHistory(userId),
          getMatchSchedule(userId)
        ]);

        if (mounted) {
          if (histRes.success && histRes.data) {
            setHistory(histRes.data);
            if (histRes.data.length > 0) {
              const firstMatch = histRes.data[0];
              setUserTeamId(
                firstMatch.home_team_name === teamName ? firstMatch.home_team_id :
                firstMatch.away_team_name === teamName ? firstMatch.away_team_id :
                firstMatch.home_team_id
              );
            }
          }
          if (schedRes.success && schedRes.data) {
            setSchedule(schedRes.data);
            if (schedRes.data.length > 0 && !userTeamId) {
              const firstMatch = schedRes.data[0];
              setUserTeamId(
                firstMatch.home_team_name === teamName ? firstMatch.home_team_id :
                firstMatch.away_team_name === teamName ? firstMatch.away_team_id :
                firstMatch.home_team_id
              );
            }
          }
        }
      } catch (err) {
        console.error('Failed to load matches', err);
      } finally {
        if (mounted) {
          setIsLoading(false);
        }
      }
    };

    fetchMatches();

    // Listen for simulation updates to refresh history
    const handleSimulation = () => fetchMatches();
    window.addEventListener('matchSimulated', handleSimulation);

    return () => {
      mounted = false;
      window.removeEventListener('matchSimulated', handleSimulation);
    };
  }, [userId, teamName]);

  return (
    <div className="flex flex-col gap-3">
      {/* TABS */}
      <div className="flex justify-center mt-1 mb-1 z-10 relative shrink-0">
        <div className="bg-black/40 p-0.5 rounded-full border border-gray-800 flex shadow-sm backdrop-blur-md relative overflow-hidden">
          <div 
            className={`absolute top-0.5 bottom-0.5 w-[48%] bg-white/10 rounded-full transition-transform duration-300 ease-out border border-white/20 ${viewMode === 'journal' ? 'translate-x-[2%]' : 'translate-x-[102%]'}`}
          ></div>
          <button
            onClick={() => setViewMode('journal')}
            className={`relative px-4 py-1 text-[10px] z-10 font-black uppercase tracking-widest rounded-full transition-colors duration-300 w-32 ${
              viewMode === 'journal'
                ? 'text-neon-pink drop-shadow-[0_0_8px_rgba(255,0,100,0.8)]'
                : 'text-gray-500 hover:text-white'
            }`}
          >
            {t.match_journal_title || 'Match Journal'}
          </button>
          <button
            onClick={() => setViewMode('schedule')}
            className={`relative px-4 py-1 text-[10px] z-10 font-black uppercase tracking-widest rounded-full transition-colors duration-300 w-32 ${
              viewMode === 'schedule'
                ? 'text-neon-cyan drop-shadow-[0_0_8px_rgba(0,240,255,0.8)]'
                : 'text-gray-500 hover:text-white'
            }`}
          >
            Schedule
          </button>
        </div>
      </div>

      <div className="bg-black/40 border border-gray-800 rounded-xl overflow-hidden shadow-[0_10px_30px_rgba(0,0,0,0.5)] flex flex-col">
        {isLoading ? (
          <div className="flex-1 flex justify-center items-center p-8">
            <div className={`w-6 h-6 border-2 border-t-transparent rounded-full animate-spin ${viewMode === 'journal' ? 'border-neon-pink' : 'border-neon-cyan'}`}></div>
          </div>
        ) : viewMode === 'journal' ? (
          history.length === 0 ? (
            <div className="flex-1 flex flex-col justify-center items-center p-8 text-gray-500">
              <p className="text-xs uppercase tracking-widest">{t.no_matches_yet || 'No matches played yet'}</p>
            </div>
          ) : (
          <div className="flex flex-col divide-y divide-gray-800/50 max-h-[175px] overflow-y-auto custom-scrollbar">
            {history.map((match) => {
              const isHome = match.home_team_id === userTeamId;
              const isWin = isHome ? match.home_score > match.away_score : match.away_score > match.home_score;
              const isDraw = match.home_score === match.away_score;
              const resultColor = isDraw ? 'text-gray-400' : isWin ? 'text-neon-green' : 'text-red-500';
              const resultLetter = isDraw ? 'D' : isWin ? 'W' : 'L';

              return (
                <button
                  key={match.id}
                  onClick={() => setSelectedReport(match)}
                  className="flex items-center justify-between p-3 hover:bg-gray-800/50 transition-colors text-left active:bg-gray-800"
                >
                  <div className="flex items-center gap-3 w-full">
                    <div className={`w-6 h-6 rounded flex items-center justify-center text-[10px] font-black shrink-0 ${isDraw ? 'bg-gray-800 text-gray-400' : isWin ? 'bg-green-900/30 text-neon-green border border-neon-green/30' : 'bg-red-900/30 text-red-500 border border-red-500/30'}`}>
                      {resultLetter}
                    </div>
                    <div className="flex flex-1 items-center gap-1 min-w-0">
                      <span className={`flex-1 text-xs font-bold truncate text-right ${isHome ? 'text-white' : 'text-gray-400'}`}>
                        {match.home_team_name}
                      </span>
                      <span className="w-14 shrink-0 text-xs font-black text-white font-orbitron text-center">
                        {match.home_score} - {match.away_score}
                      </span>
                      <span className={`flex-1 text-xs font-bold truncate text-left ${!isHome ? 'text-white' : 'text-gray-400'}`}>
                        {match.away_team_name}
                      </span>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
          )
        ) : (
          schedule.length === 0 ? (
            <div className="flex-1 flex flex-col justify-center items-center p-8 text-gray-500">
              <p className="text-xs uppercase tracking-widest text-center">No upcoming matches.<br/>League filling.</p>
            </div>
          ) : (
            <div className="flex flex-col divide-y divide-gray-800/50 max-h-[175px] overflow-y-auto custom-scrollbar">
              {schedule.map((match) => {
                const isHome = match.home_team_id === userTeamId;
                return (
                  <div key={match.id} className="flex items-center justify-between p-3 bg-gray-900/20 text-left">
                    <div className="flex items-center gap-3 w-full">
                      <div className="w-6 h-6 rounded flex items-center justify-center text-[10px] font-black shrink-0 bg-neon-cyan/10 text-neon-cyan border border-neon-cyan/30">
                        {match.round_number}
                      </div>
                      <div className="flex flex-1 items-center gap-1 min-w-0">
                        <span className={`flex-1 text-xs font-bold truncate text-right ${isHome ? 'text-white' : 'text-gray-400'}`}>
                          {match.home_team_name}
                        </span>
                        <span className="w-14 shrink-0 text-[10px] font-black text-neon-cyan/70 font-orbitron text-center uppercase tracking-widest">
                          VS
                        </span>
                        <span className={`flex-1 text-xs font-bold truncate text-left ${!isHome ? 'text-white' : 'text-gray-400'}`}>
                          {match.away_team_name}
                        </span>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )
        )}
      </div>

      {selectedReport && (
        <MatchReportModal
          report={selectedReport}
          userTeamId={userTeamId}
          onClose={() => setSelectedReport(null)}
        />
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { MatchEvent } from '@/app/utils/matchEngine';
import { markMatchAsViewed } from '@/app/actions/matchActions';
import { Activity, Shield, Target, AlertCircle, RefreshCcw } from 'lucide-react';

export interface MatchReport {
  id: string;
  home_team_id: string;
  away_team_id: string;
  home_team_name: string;
  away_team_name: string;
  home_score: number;
  away_score: number;
  events: MatchEvent[];
  round_number?: number;
  stamina_drain?: {
    home: Record<string, number>;
    away: Record<string, number>;
  };
}

interface MatchReportModalProps {
  report: MatchReport;
  userTeamId: string;
  onClose: () => void;
}

export function MatchReportModal({ report, userTeamId, onClose }: MatchReportModalProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleAccept = async () => {
    setIsSubmitting(true);
    await markMatchAsViewed(report.id);
    setIsSubmitting(false);
    onClose();
  };

  const isHome = userTeamId === report.home_team_id;
  const isWin = isHome ? report.home_score > report.away_score : report.away_score > report.home_score;
  const isDraw = report.home_score === report.away_score;

  const resultColor = isDraw ? 'text-gray-400' : isWin ? 'text-neon-green' : 'text-red-500';
  const resultText = isDraw ? 'DRAW' : isWin ? 'VICTORY' : 'DEFEAT';

  const getEventIcon = (type: string) => {
    if (type === 'goal') return <Target className="w-4 h-4 text-neon-green" />;
    if (type === 'save') return <Shield className="w-4 h-4 text-neon-cyan" />;
    if (type === 'yellow_card') return <AlertCircle className="w-4 h-4 text-yellow-500" />;
    if (type === 'red_card') return <AlertCircle className="w-4 h-4 text-red-500" />;
    if (type === 'injury') return <Activity className="w-4 h-4 text-red-500" />;
    if (type === 'substitution') return <RefreshCcw className="w-4 h-4 text-blue-400" />;
    return <AlertCircle className="w-4 h-4 text-gray-500" />;
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
      <div className="w-full max-w-md bg-gray-900 border-2 border-neon-cyan rounded-xl shadow-[0_0_40px_rgba(0,240,255,0.2)] overflow-hidden flex flex-col relative animate-in fade-in zoom-in duration-300">

        {/* Header */}
        <div className="bg-gradient-to-b from-neon-cyan/20 to-transparent p-6 text-center border-b border-neon-cyan/30 relative">
          <div className={`text-sm font-black uppercase tracking-widest mb-2 ${resultColor} drop-shadow-[0_0_10px_currentColor]`}>
            {resultText}
          </div>

          <div className="flex justify-between items-center px-4">
            <div className={`flex-1 text-right text-lg font-black uppercase truncate pr-4 ${isHome ? 'text-neon-cyan' : 'text-gray-400'}`}>
              {report.home_team_name}
            </div>
            <div className="flex flex-col items-center shrink-0 w-24">
              <div className="text-4xl font-black text-white tracking-tighter">
                {report.home_score} - {report.away_score}
              </div>
            </div>
            <div className={`flex-1 text-left text-lg font-black uppercase truncate pl-4 ${!isHome ? 'text-neon-cyan' : 'text-gray-400'}`}>
              {report.away_team_name}
            </div>
          </div>
        </div>

        {/* Timeline */}
        <div className="flex-1 overflow-y-auto max-h-[40vh] p-4 bg-black/50 custom-scrollbar">
          <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest border-b border-gray-800 pb-2 mb-4 text-center">
            Match Events
          </h3>

          {report.events?.length === 0 ? (
            <div className="text-center text-sm text-gray-600 font-mono py-8">No significant events</div>
          ) : (
            <div className="flex flex-col gap-3 relative">
              <div className="absolute left-1/2 top-0 bottom-0 w-px bg-gray-800 -translate-x-1/2" />

              {report.events?.map((ev, idx) => {
                const evTeamId = ev.team === 'home' ? report.home_team_id : report.away_team_id;
                const isHomeEvent = evTeamId === report.home_team_id;
                const isUserTeam = evTeamId === userTeamId;

                return (
                  <div key={idx} className="flex items-center w-full relative z-10 my-1">
                    <div className="flex-1 pr-4 flex justify-end items-center">
                      {isHomeEvent && (
                        <div className={`flex flex-col text-right p-2 rounded-lg border w-[95%] ${isUserTeam ? 'bg-neon-cyan/10 border-neon-cyan/30' : 'bg-gray-800/80 border-gray-700'}`}>
                           <div className="flex items-center justify-end gap-1 mb-1">
                              <span className={`text-xs font-bold truncate ${isUserTeam ? 'text-white' : 'text-gray-300'}`}>{ev.player_name}</span>
                              {ev.player_id && ev.player_id !== 'sys' && (
                                <img 
                                  src={`https://api.dicebear.com/9.x/micah/svg?seed=${ev.player_id}&backgroundColor=transparent`} 
                                  alt="avatar" 
                                  className="w-4 h-4 rounded-full bg-black/50" 
                                />
                              )}
                              {getEventIcon(ev.type)}
                           </div>
                           <span className="text-[9px] text-gray-400 whitespace-normal line-clamp-2 leading-tight">{ev.details}</span>
                        </div>
                      )}
                    </div>

                    <div className="w-8 h-8 rounded-full bg-black border border-gray-700 flex items-center justify-center shrink-0 z-20 shadow-[0_0_10px_rgba(0,0,0,0.5)]">
                      <span className="text-[10px] font-orbitron font-bold text-neon-cyan">{ev.minute}'</span>
                    </div>

                    <div className="flex-1 pl-4 flex justify-start items-center">
                      {!isHomeEvent && (
                        <div className={`flex flex-col text-left p-2 rounded-lg border w-[95%] ${isUserTeam ? 'bg-neon-cyan/10 border-neon-cyan/30' : 'bg-gray-800/80 border-gray-700'}`}>
                           <div className="flex items-center justify-start gap-1 mb-1">
                              {getEventIcon(ev.type)}
                              {ev.player_id && ev.player_id !== 'sys' && (
                                <img 
                                  src={`https://api.dicebear.com/9.x/micah/svg?seed=${ev.player_id}&backgroundColor=transparent`} 
                                  alt="avatar" 
                                  className="w-4 h-4 rounded-full bg-black/50" 
                                />
                              )}
                              <span className={`text-xs font-bold truncate ${isUserTeam ? 'text-white' : 'text-gray-300'}`}>{ev.player_name}</span>
                           </div>
                           <span className="text-[9px] text-gray-400 whitespace-normal line-clamp-2 leading-tight">{ev.details}</span>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Stamina Drain Summary */}
        <div className="px-4 py-3 bg-gray-900 border-t border-gray-800 flex justify-center">
          <div className="flex items-center gap-2 text-xs text-gray-400">
            <Activity className="w-4 h-4 text-neon-pink" />
            <span>Squad Stamina Drain: <strong className="text-neon-pink">~20%</strong></span>
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-800 bg-gray-900">
          <button 
            onClick={handleAccept}
            disabled={isSubmitting}
            className="w-full py-4 rounded-lg bg-neon-cyan text-black font-black uppercase tracking-widest hover:bg-white hover:shadow-[0_0_20px_rgba(0,240,255,0.5)] transition-all disabled:opacity-50"
          >
            {isSubmitting ? 'Processing...' : 'Accept Report'}
          </button>
        </div>

      </div>
    </div>
  );
}

'use client';

import { useState, useContext } from 'react';
import { LanguageContext } from '@/components/LanguageContext';
import { dict } from '@/lib/dictionaries';

interface OnboardingFlowProps {
  userId: string;
  onSuccess: () => void;
}

export function OnboardingFlow({ userId, onSuccess }: OnboardingFlowProps) {
  const [step, setStep] = useState<1 | 2>(1);
  const { language } = useContext(LanguageContext);
  const t = dict[language as keyof typeof dict];
  const headerFontClass = language === 'ru' ? 'font-russo' : 'font-orbitron';
  const buttonFontClass = language === 'ru' ? 'font-russo' : 'font-orbitron';

  const [teamNameInput, setTeamNameInput] = useState('');
  const [isCreatingTeam, setIsCreatingTeam] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleCreateTeam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userId || !teamNameInput.trim()) return;

    setIsCreatingTeam(true);
    setErrorMsg(null);
    try {
      const res = await fetch('/api/team/create', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, teamName: teamNameInput.trim() }),
      });

      if (res.ok) {
        onSuccess();
      } else {
        const err = await res.json();
        setErrorMsg(err.error || 'Failed to create team');
      }
    } catch (error: any) {
      setErrorMsg(error.message || 'Network error');
    } finally {
      setIsCreatingTeam(false);
    }
  };

  if (step === 1) {
    return (
      <div className="flex flex-col flex-1 p-6 gap-8 justify-center min-h-screen bg-space-dark items-center text-center">
        <div className="w-24 h-24 rounded-full border-4 border-neon-cyan mb-4 flex items-center justify-center bg-black/50 shadow-[0_0_30px_rgba(0,240,255,0.4)]">
          <span className={`text-4xl text-neon-cyan ${headerFontClass}`}>FM</span>
        </div>
        <h1 className={`text-3xl font-bold text-white mb-2 tracking-wide ${headerFontClass}`}>
          {t.welcome}
        </h1>
        <p className="text-gray-300 leading-relaxed mb-8 text-base px-2">
          {t.onboarding_welcome}
        </p>
        <button 
          onClick={() => setStep(2)}
          className={`w-full max-w-xs py-4 rounded-lg font-bold text-black uppercase tracking-wider transition-all duration-300 bg-neon-cyan hover:bg-white hover:text-neon-cyan shadow-[0_0_20px_rgba(0,240,255,0.6)] ${buttonFontClass}`}
        >
          {t.onboarding_next}
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col flex-1 p-6 gap-8 justify-center min-h-screen bg-space-dark">
      <div className="bg-black/60 backdrop-blur-md p-8 rounded-2xl border border-neon-pink/50 shadow-[0_0_30px_rgba(255,0,60,0.2)]">
        <h1 className={`text-2xl font-bold text-white mb-2 text-center uppercase ${headerFontClass}`}>{t.onboarding_create_title}</h1>
        <p className="text-gray-400 text-center mb-8 text-sm">{t.onboarding_create_desc}</p>

        <form onSubmit={handleCreateTeam} className="flex flex-col gap-5">
          <div>
            <label className="text-xs text-neon-cyan uppercase tracking-widest font-bold mb-2 block">{t.onboarding_franchise_name}</label>
            <input 
              type="text" 
              value={teamNameInput}
              onChange={(e) => setTeamNameInput(e.target.value)}
              placeholder={t.onboarding_placeholder}
              required
              maxLength={30}
              className="w-full bg-black/50 border border-gray-700 text-white rounded-lg p-3 focus:outline-none focus:border-neon-cyan focus:ring-1 focus:ring-neon-cyan transition-all"
            />
          </div>

          {errorMsg && (
            <div className="text-red-400 text-xs text-center font-bold bg-red-900/30 p-2 rounded">
              {errorMsg}
            </div>
          )}

          <button 
            type="submit"
            disabled={isCreatingTeam || !teamNameInput.trim()}
            className={`w-full py-4 rounded-lg font-bold text-black uppercase tracking-wider transition-all duration-300 mt-2 ${buttonFontClass} ${
              isCreatingTeam || !teamNameInput.trim()
                ? 'bg-gray-600 cursor-not-allowed opacity-70'
                : 'bg-neon-pink hover:bg-white hover:text-neon-pink hover:shadow-[0_0_20px_rgba(255,0,60,0.6)] shadow-[0_0_10px_rgba(255,0,60,0.4)]'
            }`}
          >
            {isCreatingTeam ? t.onboarding_drafting : t.onboarding_submit}
          </button>
        </form>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { X, Activity, Zap, User, Crosshair, ChevronRight } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { bulkTrainPlayer } from '@/app/actions/playerActions';
import { healPlayer } from '@/app/actions/baseActions';
import { renamePlayerAction, retirePlayerToAcademy, quickSellPlayer } from '@/app/actions/teamActions';
import { InfoPopover } from '@/components/ui/InfoPopover';
import Link from 'next/link';
import { listPlayerAction } from '@/app/actions/marketActions';
import toast from 'react-hot-toast';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer, PolarRadiusAxis } from 'recharts';

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

interface PlayerStats {
  pace:      number;
  shooting:  number;
  passing:   number;
  defending: number;
  physical:  number;
}

interface Player {
  id:                   string;
  name:                 string;
  age:                  number;
  ovr:                  number;
  potential_limit:      number;
  position:             string;
  stamina:              number;
  stats:                PlayerStats;
  traits?:              string[];
  is_injured?:          boolean;
  injury_matches_left?: number;
  lineup_status:        string;
  is_for_sale?:         boolean;
  is_retired?:          boolean;
  seasons_played?:      number;
}

interface Props {
  player:          Player;
  userId:          string;
  onClose:         () => void;
  onTrainSuccess:  (updatedPlayer: Player, newBalance: number) => void;
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

/** Exponential building cost mirror (for display only) */
function buildingUpgradeCost(level: number) {
  return Math.floor(500 * Math.pow(level, 1.5));
}


// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export function PlayerProfileModal({ player, userId, onClose, onTrainSuccess }: Props) {
  const [fancoins,      setFancoins]      = useState<number>(0);
  const [sweatPoints,   setSweatPoints]   = useState<number>(0);
  const [medicalLevel,  setMedicalLevel]  = useState<number>(1);
  const [stadiumLevel,  setStadiumLevel]  = useState<number>(1);
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isHealing,     setIsHealing]     = useState(false);
  const [errorMsg,      setErrorMsg]      = useState<string | null>(null);

  const [sellMode,      setSellMode]      = useState(false);
  const [sellPrice,     setSellPrice]     = useState('');
  const [isPendingSell, startTransition]  = React.useTransition();

  const [renameMode,      setRenameMode]      = useState(false);
  const [newName,         setNewName]         = useState(player.name);
  const [isPendingRename, startTransitionRename] = React.useTransition();

  const [isPendingRetire, startTransitionRetire] = React.useTransition();
  const [isPendingQuickSell, startTransitionQuickSell] = React.useTransition();

  // ── Load balances + medical level ─────────────────────────────────────────

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [infraRes, userRes] = await Promise.all([
          fetch(`/api/infrastructure?userId=${userId}`),
          fetch(`/api/user/me?userId=${userId}`),
        ]);

        if (infraRes.ok) {
          const infraData = await infraRes.json();
          setMedicalLevel(infraData.infrastructure?.medical_center_level ?? 1);
          setStadiumLevel(infraData.infrastructure?.stadium_level ?? 1);
        }
        if (userRes.ok) {
          const userData = await userRes.json();
          setFancoins(userData.user?.balance_fancoins ?? 0);
          setSweatPoints(userData.user?.sweat_points ?? 0);
        }
      } catch (err) {
        console.error('[PlayerProfileModal] Failed to fetch data:', err);
      } finally {
        setIsLoadingData(false);
      }
    };
    fetchData();
  }, [userId]);

  // ── Computed ──────────────────────────────────────────────────────────────

  const stats = player.stats || { pace: 50, shooting: 50, passing: 50, defending: 50, physical: 50 };

  const cost = Math.max(0, 100 - (player.stamina ?? 100));
  const canAffordHeal = sweatPoints >= cost;

  // ── Heal handler ─────────────────────────────────────────────────────────

  const handleHeal = async () => {
    if (!canAffordHeal || isHealing) return;
    setIsHealing(true);
    setErrorMsg(null);

    try {
      const res = await healPlayer(userId, player.id);
      if (res.success) {
        const newBal = res.new_balance ?? sweatPoints - cost;
        setSweatPoints(newBal);
        window.dispatchEvent(new Event('balanceUpdated'));
        const updatedPlayer = { ...player, stamina: 100, is_injured: false, injury_matches_left: 0 };
        onTrainSuccess(updatedPlayer as Player, newBal);
      } else {
        setErrorMsg(res.error ?? 'Healing failed');
      }
    } catch {
      setErrorMsg('Network error occurred.');
    } finally {
      setIsHealing(false);
    }
  };

  // ── Sell handler ─────────────────────────────────────────────────────────
  const handleSell = () => {
    const price = parseFloat(sellPrice);
    if (isNaN(price) || price <= 0) {
      toast.error('Введите корректную цену в TON');
      return;
    }
    const fee = stadiumLevel * 250;
    if (fancoins < fee) {
      toast.error(`Недостаточно FanCoins для налога. Нужно: ${fee} FC`);
      return;
    }
    if (player.lineup_status === 'starting' || player.lineup_status === 'bench') {
      toast.error('Игрок в составе. Сначала переведите его в резерв.');
      return;
    }

    startTransition(async () => {
      const res = await listPlayerAction(player.id, price);
      if (res.success) {
        toast.success(`Игрок выставлен на рынок за ${price} TON`);
        window.dispatchEvent(new Event('balanceUpdated'));
        onClose(); // Close modal on success
      } else {
        toast.error(res.error || 'Ошибка при выставлении на рынок');
      }
    });
  };

  // ── Rename handler ───────────────────────────────────────────────────────
  const handleRename = () => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed.length < 3) {
      toast.error('Имя должно содержать минимум 3 символа');
      return;
    }
    if (fancoins < 1000) {
      toast.error('Недостаточно FanCoins для переименования (Нужно: 1000 FC)');
      return;
    }

    startTransitionRename(async () => {
      const res = await renamePlayerAction(player.id, trimmed);
      if (res.success) {
        toast.success(`Игрок успешно переименован в ${trimmed}!`);
        window.dispatchEvent(new Event('balanceUpdated'));
        setFancoins(prev => prev - 1000);
        player.name = trimmed; // optimistic update
        setRenameMode(false);
      } else {
        toast.error(res.error || 'Ошибка при переименовании');
      }
    });
  };

  // ── Retire handler ───────────────────────────────────────────────────────
  const handleRetire = () => {
    startTransitionRetire(async () => {
      const res = await retirePlayerToAcademy(player.id);
      if (res.success) {
        toast.success(`Перк тренера успешно применен к Академии!`);
        onClose(); // Close modal on success (player is burnt)
      } else {
        toast.error(res.error || 'Ошибка при применении перка');
      }
    });
  };

  // ── Quick Sell handler ───────────────────────────────────────────────────
  const handleQuickSell = () => {
    if (confirm(`Вы уверены, что хотите продать ${player.name} системе? Это действие нельзя отменить.`)) {
      startTransitionQuickSell(async () => {
        const res = await quickSellPlayer(player.id);
        if (res.success) {
          toast.success(`Игрок успешно продан системе за ${res.payout} FC!`);
          onClose();
        } else {
          toast.error(res.error || 'Ошибка при продаже игрока');
        }
      });
    }
  };

  // ── Stat display config ───────────────────────────────────────────────────

  const statLabels: Record<keyof PlayerStats, string> = {
    pace:      'PAC',
    shooting:  'SHO',
    passing:   'PAS',
    defending: 'DEF',
    physical:  'PHY',
  };

  const statColors: Record<keyof PlayerStats, string> = {
    pace:      'bg-neon-cyan',
    shooting:  'bg-neon-pink',
    passing:   'bg-yellow-400',
    defending: 'bg-blue-500',
    physical:  'bg-green-500',
  };

  // ─────────────────────────────────────────────────────────────────────────
  // Render
  // ─────────────────────────────────────────────────────────────────────────

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 10 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 10 }}
        className="w-full max-w-sm bg-gray-950 border border-neon-cyan/50 shadow-[0_0_30px_rgba(0,255,255,0.15)] rounded-2xl overflow-hidden relative flex flex-col max-h-[90vh]"
      >
        {/* ── Header ─────────────────────────────────────────────────────── */}
        <div className="p-5 border-b border-gray-800 flex justify-between items-start bg-gradient-to-b from-neon-cyan/10 to-transparent flex-shrink-0">
          <div className="flex gap-4 items-center">
            <div className="relative w-16 h-16 rounded-xl bg-black/60 border border-neon-cyan/40 shadow-[inset_0_0_15px_rgba(0,255,255,0.2)] flex items-center justify-center overflow-hidden">
              <img 
                src={`https://api.dicebear.com/9.x/micah/svg?seed=${player.id}&backgroundColor=transparent`}
                alt="Avatar"
                className="w-full h-full object-cover opacity-90 mix-blend-screen"
              />
              <div className="absolute bottom-0 left-0 right-0 bg-black/70 flex justify-center items-center py-0.5 border-t border-neon-cyan/30">
                <span className="text-[10px] font-black text-white">{player.ovr}</span>
                <span className="text-[8px] font-bold text-neon-cyan ml-1">{player.position}</span>
              </div>
            </div>
            <div>
              <h2 className="text-lg font-black text-white uppercase tracking-wider flex items-center gap-2">
                {player.name}
                {!player.is_retired && !player.is_for_sale && (
                  <button onClick={() => setRenameMode(true)} className="p-1 hover:bg-gray-800 rounded-md transition-colors text-gray-500 hover:text-neon-cyan" title="Rename Player (1000 FC)">
                    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg>
                  </button>
                )}
                {player.is_injured && (
                  <span className="text-[10px] bg-red-900/40 text-red-400 px-1 py-0.5 rounded border border-red-500/50 animate-pulse">
                    🚑 {player.injury_matches_left}M
                  </span>
                )}
              </h2>
              <div className="flex flex-col gap-1 mt-1">
                <div className="flex items-center gap-2 text-xs font-bold font-orbitron">
                  <span className={`px-1.5 py-0.5 rounded ${player.age >= 35 ? 'bg-purple-900/50 text-purple-400 border border-purple-500/50' : player.age >= 31 ? 'bg-red-900/40 text-red-400 border border-red-500/50' : 'bg-gray-800 text-gray-400 border border-gray-700'}`}>
                    {player.age} YO
                  </span>
                  {player.age >= 31 && !player.is_retired && (
                    <span className="text-[9px] text-red-500 uppercase tracking-widest bg-red-900/20 px-1 rounded">Decay</span>
                  )}
                </div>
                <div className="flex items-center gap-1 text-xs text-gray-400 mt-1">
                  <Activity size={12} className={player.stamina > 50 ? 'text-neon-green' : 'text-red-500'} />
                  <span>Stamina: {player.stamina}%</span>
                </div>
                <div className="flex items-center gap-1 text-[10px] text-gray-500 font-orbitron">
                  <span>POTENTIAL:</span>
                  <span className="text-neon-pink font-bold">{player.potential_limit}</span>
                </div>
              </div>
            </div>
          </div>
          <button onClick={onClose} className="p-1 text-gray-500 hover:text-white transition-colors bg-black/40 rounded-full border border-gray-800 hover:border-gray-600">
            <X size={20} />
          </button>
        </div>

        {/* ── Content ────────────────────────────────────────────────────── */}
        <div className="overflow-y-auto custom-scrollbar flex-1 p-5 flex flex-col gap-5">

          {sellMode ? (
            <div className="flex flex-col gap-4 animate-in fade-in duration-300">
              <h3 className="text-sm font-black text-white uppercase tracking-widest text-center">Выставить на рынок</h3>
              <p className="text-xs text-gray-400 text-center -mt-2">Продажа NFT-карточки за TON</p>

              <div className="bg-black/50 p-4 rounded-xl border border-gray-800">
                <label className="text-xs text-gray-400 font-bold uppercase tracking-widest">Цена (TON)</label>
                <div className="flex items-center gap-2 mt-2">
                  <span className="text-xl">💎</span>
                  <input 
                    type="number" 
                    step="0.01"
                    min="0"
                    value={sellPrice}
                    onChange={(e) => setSellPrice(e.target.value)}
                    placeholder="Например: 1.5"
                    className="flex-1 w-0 bg-gray-900 border border-gray-700 rounded-lg p-3 text-white font-orbitron text-xl focus:border-neon-cyan outline-none transition-colors"
                  />
                </div>
              </div>

              <div className="bg-red-900/20 border border-red-500/30 p-4 rounded-xl flex flex-col gap-2">
                <div className="flex justify-between text-xs text-red-400 font-bold uppercase tracking-widest">
                  <span>Налог на размещение (Fee):</span>
                  <span>{stadiumLevel * 250} FC</span>
                </div>
                <p className="text-[10px] text-red-500/70">
                  Этот налог высчитывается из уровня вашего Стадиона ({stadiumLevel} ур.) и будет сожжен навсегда.
                </p>
              </div>

              <div className="flex gap-3 mt-2">
                <button 
                  onClick={() => setSellMode(false)}
                  disabled={isPendingSell}
                  className="flex-1 py-3 rounded-lg font-bold uppercase tracking-widest text-xs bg-gray-800 text-white hover:bg-gray-700 disabled:opacity-50 transition-colors"
                >
                  Отмена
                </button>
                <button 
                  onClick={handleSell}
                  disabled={isPendingSell || !sellPrice}
                  className="flex-1 py-3 rounded-lg font-black uppercase tracking-widest text-xs bg-blue-600 text-white hover:bg-blue-500 disabled:opacity-50 transition-colors shadow-[0_0_15px_rgba(37,99,235,0.4)]"
                >
                  {isPendingSell ? 'Загрузка...' : 'Подтвердить'}
                </button>
              </div>
            </div>
          ) : renameMode ? (
            <div className="flex flex-col gap-4 animate-in fade-in duration-300">
              <h3 className="text-sm font-black text-white uppercase tracking-widest text-center">Изменить Имя</h3>
              <p className="text-xs text-gray-400 text-center -mt-2">Каждое имя уникально во всей игре</p>

              <div className="bg-black/50 p-4 rounded-xl border border-gray-800">
                <label className="text-xs text-gray-400 font-bold uppercase tracking-widest">Новое Имя</label>
                <div className="flex items-center gap-2 mt-2">
                  <input 
                    type="text" 
                    maxLength={25}
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    placeholder="Например: Cyber Striker"
                    className="flex-1 w-0 bg-gray-900 border border-gray-700 rounded-lg p-3 text-white font-orbitron focus:border-neon-pink outline-none transition-colors"
                  />
                </div>
              </div>

              <div className="bg-yellow-900/20 border border-yellow-500/30 p-4 rounded-xl flex flex-col gap-2">
                <div className="flex justify-between text-xs text-yellow-400 font-bold uppercase tracking-widest">
                  <span>Стоимость услуги:</span>
                  <span>1000 FC</span>
                </div>
                <p className="text-[10px] text-yellow-500/70">
                  Новое имя должно быть уникальным и не содержать нецензурную лексику. Реальные имена мировых звезд (Messi, Ronaldo) защищены лицензией FIFPro и запрещены.
                </p>
              </div>

              <div className="flex gap-3 mt-2">
                <button 
                  onClick={() => { setRenameMode(false); setNewName(player.name); }}
                  disabled={isPendingRename}
                  className="flex-1 py-3 rounded-lg font-bold uppercase tracking-widest text-xs bg-gray-800 text-white hover:bg-gray-700 disabled:opacity-50 transition-colors"
                >
                  Отмена
                </button>
                <button 
                  onClick={handleRename}
                  disabled={isPendingRename || !newName || newName === player.name}
                  className="flex-1 py-3 rounded-lg font-black uppercase tracking-widest text-xs bg-yellow-600 text-black hover:bg-yellow-500 disabled:opacity-50 transition-colors shadow-[0_0_15px_rgba(202,138,4,0.4)]"
                >
