              {errorMsg}
            </div>
          )}

          {/* ── Stats ────────────────────────────────────────────────────── */}
          <div>
            <h3 className="text-[10px] uppercase tracking-widest text-gray-500 mb-3 flex items-center gap-2 z-10 relative">
              <Zap size={12} className="text-neon-pink" /> Detailed Stats
              <InfoPopover
                title="Характеристики"
                content={
                  <div className="space-y-2">
                    <p><strong className="text-neon-cyan">PAC:</strong> Скорость игрока. Влияет на перемещение по полю.</p>
                    <p><strong className="text-neon-pink">SHO:</strong> Удары. Точность и сила ударов по воротам.</p>
                    <p><strong className="text-yellow-400">PAS:</strong> Пасы. Успешность передач и видение поля.</p>
                    <p><strong className="text-blue-500">DEF:</strong> Защита. Отбор мяча и перехваты.</p>
                    <p><strong className="text-green-500">PHY:</strong> Физика. Выносливость и игра корпусом.</p>
                  </div>
                }
              />
            </h3>

            <div className="relative -mt-10 mb-[-20px] h-[220px] w-full flex justify-center items-center pointer-events-none">
              <ResponsiveContainer width="100%" height="100%">
                <RadarChart 
                  cx="50%" 
                  cy="50%" 
                  outerRadius="65%" 
                  data={[
                    { subject: 'PAC', A: stats.pace, fullMark: 100 },
                    { subject: 'SHO', A: stats.shooting, fullMark: 100 },
                    { subject: 'PAS', A: stats.passing, fullMark: 100 },
                    { subject: 'PHY', A: stats.physical, fullMark: 100 },
                    { subject: 'DEF', A: stats.defending, fullMark: 100 },
                  ]}
                >
                  <PolarGrid stroke="#334155" opacity={0.5} />
                  <PolarAngleAxis 
                    dataKey="subject" 
                    tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 'bold' }} 
                  />
                  <PolarRadiusAxis angle={90} domain={[0, 100]} tick={false} axisLine={false} />
                  <Radar
                    name="Player Stats"
                    dataKey="A"
                    stroke="#00f0ff"
                    strokeWidth={2}
                    fill="#00f0ff"
                    fillOpacity={0.4}
                  />
                </RadarChart>
              </ResponsiveContainer>
            </div>

            <div className="flex flex-col gap-3 relative z-10">
              {(Object.keys(statLabels) as Array<keyof PlayerStats>).map(key => (
                <div key={key} className="flex items-center gap-3">
                  <span className="text-xs font-bold text-gray-300 w-12 uppercase tracking-wider">{statLabels[key]}</span>
                  <div className="flex-1 h-1.5 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
                    <div
                      className={`h-full ${statColors[key]} transition-all duration-1000`}
                      style={{ width: `${Math.min(100, Math.max(0, stats[key]))}%` }}
                    />
                  </div>
                  <span className="text-xs font-black text-white w-6 text-right">{stats[key]}</span>
                </div>
              ))}
            </div>
          </div>

          {/* ── Traits ───────────────────────────────────────────────────── */}
          <div>
            <h3 className="text-[10px] uppercase tracking-widest text-gray-500 mb-3 border-t border-gray-800 pt-4 flex items-center gap-2">
              <Crosshair size={12} className="text-purple-400" /> Special Traits
            </h3>
            <div className="flex flex-wrap gap-2">
              {player.traits && player.traits.length > 0 ? (
                player.traits.map(trait => (
                  <span key={trait} className="px-2 py-1 text-[10px] font-black uppercase tracking-widest bg-purple-900/40 text-purple-300 border border-purple-500/50 rounded-md shadow-[0_0_10px_rgba(168,85,247,0.2)]">
                    {trait}
                  </span>
                ))
              ) : (
                <span className="text-xs text-gray-600 italic">No special traits</span>
              )}
            </div>
          </div>

          {/* ── Heal Section (FC, Medical Center discount) ───────────────── */}
          {(player.stamina < 100 || player.is_injured) && (
            <div className="border-t border-gray-800 pt-4">
              <h3 className="text-[10px] uppercase tracking-widest text-gray-500 mb-3 flex items-center justify-between">
                <span>Медпункт (Lv {medicalLevel})</span>
                <span className="text-yellow-400 font-mono">
                  {isLoadingData ? '...' : `${fancoins.toLocaleString()} FC`}
                </span>
              </h3>

              <div className="flex items-center justify-between bg-black/50 p-3 rounded-xl border border-gray-800">
                <div className="flex flex-col gap-1">
                  {/* Stamina bar */}
                  <div className="flex items-center gap-2">
                    <div className="w-28 h-1.5 bg-gray-800 rounded-full overflow-hidden border border-gray-700">
                      <div
                        className="h-full bg-orange-500 transition-all"
                        style={{ width: `${player.stamina}%` }}
                      />
                    </div>
                    <span className="text-xs font-mono text-orange-400">{player.stamina}/100</span>
                  </div>
                  {/* Discount note */}
                  {medicalLevel > 1 && (
                    <span className="text-[9px] text-emerald-500 font-mono">
                      −{Math.min(medicalLevel * 5, 50)}% скидка Медпункта
                    </span>
                  )}
                </div>

                <button
                  id={`heal-btn-${player.id}`}
                  onClick={handleHeal}
                  disabled={!canAffordHeal || isHealing || isLoadingData}
                  className={`
                    px-3 py-2 rounded-xl text-[10px] font-bold uppercase tracking-wider
                    transition-all duration-200 border flex flex-col items-center
                    ${isHealing
                      ? 'bg-transparent text-neon-green border-neon-green/50 opacity-50'
                      : canAffordHeal
                      ? 'bg-neon-green/10 text-neon-green border-neon-green hover:bg-neon-green hover:text-black shadow-[0_0_10px_rgba(57,255,20,0.3)] active:scale-95'
                      : 'bg-gray-800 text-gray-500 border-gray-700 cursor-not-allowed'
                    }
                  `}
                >
                  <span>{isHealing ? '...' : 'Heal'}</span>
                  <span className="text-[8px] font-mono opacity-75">{isLoadingData ? '...' : cost === 0 ? 'Free' : `${cost} SP`}</span>
                </button>
              </div>
            </div>
          )}

            </div>
          )}

          {/* ── Footer Actions ─────────────────────────────────────────────── */}
          <div className="border-t border-gray-800 pt-4 flex flex-col gap-3">
            {player.is_for_sale ? (
              <div className="w-full py-3 bg-gray-900 border border-gray-700 rounded-xl text-center text-xs font-bold text-gray-500 uppercase tracking-widest">
                Игрок выставлен на рынок
              </div>
            ) : player.is_retired ? (
              <div className="flex gap-3">
                <button 
                  onClick={() => setSellMode(true)}
                  className="flex-1 py-3 rounded-xl bg-blue-900/30 border border-blue-500/50 text-blue-400 font-black text-xs uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all shadow-[0_0_10px_rgba(59,130,246,0.1)]"
                >
                  Продать на рынке (TON)
                </button>
                <button 
                  onClick={handleRetire}
                  disabled={isPendingRetire}
                  className="flex-1 py-3 rounded-xl bg-purple-900/30 border border-purple-500/50 text-purple-400 font-black text-xs uppercase tracking-widest hover:bg-purple-600 hover:text-white transition-all shadow-[0_0_10px_rgba(168,85,247,0.1)]"
                >
                  {isPendingRetire ? 'Применение...' : 'Превратить в Тренера'}
                </button>
              </div>
            ) : (
              <div className="flex flex-col gap-3">
                <div className="flex gap-3">
                  <button 
                    onClick={() => setSellMode(true)}
                    className="flex-1 py-3 rounded-xl bg-blue-900/30 border border-blue-500/50 text-blue-400 font-black text-xs uppercase tracking-widest hover:bg-blue-600 hover:text-white transition-all shadow-[0_0_10px_rgba(59,130,246,0.1)]"
                  >
                    На рынок (TON)
                  </button>
                  <button 
                    onClick={handleQuickSell}
                    disabled={isPendingQuickSell || player.lineup_status === 'starting'}
                    className="flex-1 py-3 rounded-xl bg-orange-900/30 border border-orange-500/50 text-orange-400 font-black text-xs uppercase tracking-widest hover:bg-orange-600 hover:text-white transition-all shadow-[0_0_10px_rgba(249,115,22,0.1)] disabled:opacity-50 disabled:cursor-not-allowed"
                    title={player.lineup_status === 'starting' ? 'Сначала переведите игрока в запас' : ''}
                  >
                    {isPendingQuickSell ? 'Продажа...' : `Системе (${Math.max(100, (player.ovr - 40) * 100)} FC)`}
                  </button>
                </div>
                <Link
                  href={`/base?playerId=${player.id}`}
                  onClick={onClose}
                  className="w-full py-3 rounded-xl bg-neon-cyan/20 border border-neon-cyan/50 text-neon-cyan font-black text-xs uppercase tracking-widest hover:bg-neon-cyan hover:text-black flex items-center justify-center transition-all shadow-[0_0_10px_rgba(0,255,255,0.2)]"
                >
                  Тренировать
                </Link>
              </div>
            )}
          </div>

        </div>
      </motion.div>
    </div>
  );
}

'use client';

import { useState, useTransition, useCallback } from 'react';
import { toast } from 'react-hot-toast';
import { Footprints, Zap, ArrowRightLeft, FlaskConical, Flame, Dumbbell, CircleDot } from 'lucide-react';
import {
  syncStepsAction,
  convertSweatPointsAction,
  type ManagerProfileType,
  type CurrencyType,
  type SyncStepsResult,
  type ConvertSpResult,
} from '@/app/actions/economyActions';
import { dict } from '@/lib/dictionaries';

// ─────────────────────────────────────────────────────────────────────────────
// Constants & Helpers
// ─────────────────────────────────────────────────────────────────────────────

const DAILY_STEP_CAP = 20_000;

// Profile labels moved inside component to support translations

// Multiplier matrix (mirrors DB logic — used only for local preview)
const MULTIPLIER_MATRIX: Record<ManagerProfileType, Record<CurrencyType, number>> = {
  runner:      { cardio: 1.0, fitness: 0.6, ball: 0.4, strength: 0.2 },
  yogi:        { cardio: 0.6, fitness: 1.0, ball: 0.4, strength: 0.2 },
  ball_player: { cardio: 0.2, fitness: 0.6, ball: 1.0, strength: 0.4 },
  lifter:      { cardio: 0.2, fitness: 0.4, ball: 0.6, strength: 1.0 },
};

const CURRENCY_META: Record<CurrencyType, { label: string; icon: React.ReactNode; accent: string; glow: string }> = {
  cardio:   { label: 'Cardio Coin',    icon: <Flame size={16} />,      accent: 'text-orange-400',  glow: 'shadow-[0_0_10px_rgba(251,146,60,0.4)]'   },
  fitness:  { label: 'Fitness Coin',   icon: <FlaskConical size={16} />, accent: 'text-purple-400', glow: 'shadow-[0_0_10px_rgba(192,132,252,0.4)]' },
  ball:     { label: 'Ball Coin',      icon: <CircleDot size={16} />,   accent: 'text-yellow-400',  glow: 'shadow-[0_0_10px_rgba(250,204,21,0.4)]'   },
  strength: { label: 'Strength Coin',  icon: <Dumbbell size={16} />,    accent: 'text-red-400',     glow: 'shadow-[0_0_10px_rgba(248,113,113,0.4)]'  },
};

function multiplierBadge(mult: number): string {
  if (mult >= 0.9) return 'text-neon-green bg-neon-green/10 border-neon-green/30';
  if (mult >= 0.5) return 'text-yellow-400 bg-yellow-400/10 border-yellow-400/30';
  return 'text-gray-500 bg-gray-800/40 border-gray-700/40';
}

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────

interface SweatBankClientProps {
  initialData: {
    manager_profile: ManagerProfileType;
    daily_steps: number;
    sweat_points: number;
    cardio_coin: number;
    fitness_coin: number;
    ball_coin: number;
    strength_coin: number;
  };
  language: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// Main Component
// ─────────────────────────────────────────────────────────────────────────────

export function SweatBankClient({ initialData, language }: SweatBankClientProps) {
  const t = dict[language as keyof typeof dict];

  // Local mirrors of server state — updated optimistically on action success
  const [dailySteps, setDailySteps] = useState(initialData.daily_steps);
  const [sweatPoints, setSweatPoints] = useState(initialData.sweat_points);
  const [coinBalances, setCoinBalances] = useState({
    cardio:   initialData.cardio_coin,
    fitness:  initialData.fitness_coin,
    ball:     initialData.ball_coin,
    strength: initialData.strength_coin,
  });
  const profile = initialData.manager_profile;

  const PROFILE_LABELS: Record<ManagerProfileType, { label: string; emoji: string; color: string }> = {
    runner:      { label: t.profile_runner, emoji: '🏃', color: 'text-neon-green' },
    yogi:        { label: t.profile_yogi,   emoji: '🧘', color: 'text-purple-400' },
    ball_player: { label: t.profile_ball,   emoji: '⚽', color: 'text-yellow-400' },
    lifter:      { label: t.profile_lifter, emoji: '🏋️', color: 'text-red-400' },
  };

  // Exchange inputs: one integer input per currency
  const [spInputs, setSpInputs] = useState<Record<CurrencyType, string>>({
    cardio: '', fitness: '', ball: '', strength: '',
  });

  const [isSyncing, startSyncTransition] = useTransition();
  const [isConverting, startConvertTransition] = useTransition();

  // ── Step Sync ──────────────────────────────────────────────────────────────

  const handleSyncSteps = useCallback((amount: number) => {
    startSyncTransition(async () => {
      const res = await syncStepsAction(amount);
      if (res.success && res.data) {
        const d = res.data as SyncStepsResult;
        setDailySteps(d.daily_steps);
        setSweatPoints(d.total_sp);
        toast.success(t.toast_sync_success.replace('{sp}', d.sp_gained.toString()).replace('{steps}', d.added_steps.toString()));
      } else {
        toast.error(res.error ?? t.toast_sync_error);
      }
    });
  }, []);

  // ── Conversion ─────────────────────────────────────────────────────────────

  const handleConvert = useCallback((currency: CurrencyType) => {
    const raw = spInputs[currency];
    const amount = parseInt(raw, 10);
    if (!raw || isNaN(amount) || amount <= 0) {
      toast.error(t.toast_invalid_sp);
      return;
    }
    if (amount > sweatPoints) {
      toast.error(t.toast_insufficient_sp);
      return;
    }

    startConvertTransition(async () => {
      const res = await convertSweatPointsAction(currency, amount);
      if (res.success && res.data) {
        const d = res.data as ConvertSpResult;
        setSweatPoints(d.new_balance_sp);
        setCoinBalances(prev => ({ ...prev, [currency]: d.new_balance_currency }));
        setSpInputs(prev => ({ ...prev, [currency]: '' }));
        toast.success(t.toast_convert_success.replace('{coins}', d.gained_coins.toString()).replace('{coinName}', CURRENCY_META[currency].label));
      } else {
        toast.error(res.error ?? t.toast_convert_error);
      }
    });
  }, [spInputs, sweatPoints]);

  const profileMeta = PROFILE_LABELS[profile];
  const stepPct = Math.min((dailySteps / DAILY_STEP_CAP) * 100, 100);

  // ── Render ─────────────────────────────────────────────────────────────────

  return (
    <div className="flex flex-col gap-4 p-4 pb-6">

      {/* ── BLOCK 1: Pedometer ─────────────────────────────────────────────── */}
      <section className="bg-black/40 border border-gray-800 rounded-2xl p-4 flex flex-col gap-3">
        <div className="flex items-center gap-2">
          <Footprints className="text-neon-green w-5 h-5" />
          <h2 className="text-sm font-black uppercase tracking-widest text-neon-green drop-shadow-[0_0_5px_rgba(57,255,20,0.5)]">
            {t.pedometer}
          </h2>
        </div>

        {/* Step progress bar */}
        <div className="flex flex-col gap-1">
          <div className="flex justify-between items-end">
            <span className="text-2xl font-black text-white tabular-nums font-orbitron">
              {dailySteps.toLocaleString()}
            </span>
            <span className="text-xs text-gray-500 font-bold">/ {DAILY_STEP_CAP.toLocaleString()} {t.steps_lower}</span>
          </div>
          <div className="h-2.5 rounded-full bg-gray-800 overflow-hidden">
            <div
              className="h-full rounded-full bg-gradient-to-r from-neon-green to-cyan-400 transition-all duration-700 ease-out shadow-[0_0_8px_rgba(57,255,20,0.5)]"
              style={{ width: `${stepPct}%` }}
            />
          </div>
          <div className="flex justify-between text-[10px] text-gray-600 font-bold">
            <span>0</span>
            <span className="text-gray-500">{stepPct.toFixed(1)}%</span>
            <span>20K</span>
          </div>
        </div>

        {/* SP Balance */}
        <div className="flex items-center justify-between bg-neon-green/5 border border-neon-green/20 rounded-xl px-4 py-2.5">
          <div className="flex items-center gap-2">
            <Zap className="text-neon-green w-4 h-4" />
            <span className="text-xs uppercase tracking-widest font-bold text-gray-400">Sweat Points</span>
          </div>
          <span className="text-xl font-black text-neon-green font-orbitron drop-shadow-[0_0_8px_rgba(57,255,20,0.6)]">
            {sweatPoints.toLocaleString()}
          </span>
        </div>

        {/* DEBUG UI */}
        <div className="flex flex-col gap-1.5">
          <p className="text-[9px] uppercase tracking-widest text-gray-600 font-bold flex items-center gap-1">
            <FlaskConical size={10} />
            {t.debug_mode}
          </p>
          <div className="flex gap-2">
            {[1000, 5500].map(amt => (
              <button
                key={amt}
                onClick={() => handleSyncSteps(amt)}
                disabled={isSyncing}
                className={`flex-1 py-2 rounded-lg text-[10px] font-black uppercase tracking-wider border transition-all ${
                  isSyncing
                    ? 'bg-gray-800 text-gray-600 border-gray-700 cursor-not-allowed'
                    : 'bg-neon-green/10 text-neon-green border-neon-green/40 hover:bg-neon-green/20 active:scale-95'
                }`}
              >
                {isSyncing ? '...' : `+${amt.toLocaleString()} ${t.steps_lower}`}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* ── BLOCK 2: Manager Profile ────────────────────────────────────────── */}
      <section className="bg-black/40 border border-gray-800 rounded-2xl p-4 flex flex-col gap-3">
        <div className="flex items-center justify-between">
