'use client';

import { useState, useEffect } from 'react';
import { SquadManager } from './SquadManager';
import { getUpcomingOpponentScoutReport, ScoutReport } from '@/app/actions/scoutActions';
import { ShieldAlert, Crosshair, Lock } from 'lucide-react';

export function SquadTabs({ initialPlayers, teamId, userId }: { initialPlayers: any[], teamId: string, userId: string }) {
  const [activeTab, setActiveTab] = useState<'lineup' | 'scout'>('lineup');
  const [report, setReport] = useState<ScoutReport | null>(null);
  const [isLoadingScout, setIsLoadingScout] = useState(false);

  useEffect(() => {
    if (activeTab === 'scout' && !report) {
      setIsLoadingScout(true);
      getUpcomingOpponentScoutReport(userId).then(res => {
        if (res.success && res.data) {
          setReport(res.data);
        }
        setIsLoadingScout(false);
      });
    }
  }, [activeTab, userId, report]);

  return (
    <div className="flex flex-col gap-4">
      {/* Tabs */}
      <div className="flex bg-black/40 border border-gray-800 p-1 rounded-lg">
        <button 
          onClick={() => setActiveTab('lineup')}
          className={`flex-1 py-2 text-xs font-bold uppercase tracking-widest rounded-md transition-all duration-300 ${activeTab === 'lineup' ? 'bg-neon-cyan text-black shadow-[0_0_15px_rgba(0,240,255,0.4)]' : 'text-gray-400 hover:text-white'}`}
        >
          Lineup
        </button>
        <button 
          onClick={() => setActiveTab('scout')}
          className={`flex-1 py-2 text-xs font-bold uppercase tracking-widest rounded-md transition-all duration-300 ${activeTab === 'scout' ? 'bg-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.5)]' : 'text-gray-400 hover:text-white'}`}
        >
          Scout Intel
        </button>
      </div>

      {/* Content */}
      {activeTab === 'lineup' ? (
        <SquadManager initialPlayers={initialPlayers} teamId={teamId} />
      ) : (
        <div className="flex flex-col border border-gray-800 bg-black/60 rounded-xl overflow-hidden min-h-[300px] animate-in fade-in duration-300">
          {isLoadingScout ? (
            <div className="flex-1 flex justify-center items-center py-12">
               <div className="w-8 h-8 border-2 border-red-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
          ) : !report || (report.players.length === 0 && report.fog_level !== 'hidden') ? (
            <div className="flex-1 flex flex-col items-center justify-center py-12 text-gray-500">
              <ShieldAlert className="w-12 h-12 mb-4 opacity-50 text-red-500" />
              <p className="text-sm uppercase tracking-widest font-bold">Scouts found no intel</p>
              <p className="text-xs mt-2 text-center max-w-xs">Data is restricted or opponent roster is empty.</p>
            </div>
          ) : (
            <div className="flex flex-col">
              <div className="bg-gradient-to-r from-red-900/30 to-transparent p-4 border-b border-red-900/30 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 rounded-full bg-black border border-red-500 flex items-center justify-center shadow-[0_0_15px_rgba(239,68,68,0.4)]">
                    <Crosshair className="w-6 h-6 text-red-500" />
                  </div>
                  <div>
                    <h3 className="text-white text-lg font-black uppercase tracking-wider font-orbitron">{report.opponent_team_name}</h3>
                    <p className="text-[10px] text-red-400 uppercase tracking-widest">Next Target (Round {report.round_number})</p>
                  </div>
                </div>
                <div className="flex flex-col items-end">
                  <span className="text-[9px] uppercase tracking-widest text-red-500/70 font-bold">Team OVR</span>
                  <span className="text-xl font-black text-red-500 drop-shadow-[0_0_5px_rgba(239,68,68,0.5)]">
                    {report.fog_level === 'full' ? report.team_ovr_estimated : `~${report.team_ovr_estimated}`}
                  </span>
                </div>
              </div>

              {report.fog_level === 'hidden' ? (
                <div className="flex-1 flex flex-col items-center justify-center py-16 text-center">
                  <Lock className="w-10 h-10 text-red-900 mb-3" />
                  <p className="text-sm uppercase tracking-widest font-black text-red-500">Отдел Скаутов Ур. 3</p>
                  <p className="text-[10px] uppercase tracking-widest text-gray-500 mt-2 max-w-[200px]">
                    Требуется для просмотра состава противника
                  </p>
                </div>
              ) : (
                <div className="p-4 flex flex-col gap-2">
                  <div className="flex items-center justify-between px-2 text-[10px] text-gray-500 font-bold uppercase tracking-widest mb-1 border-b border-gray-800 pb-2">
                    <div className="w-10 text-center">POS</div>
                    <div className="flex-1 px-3">OPERATIVE</div>
                    <div className="w-16 text-center text-red-500">EST. OVR</div>
                  </div>

                  {report.players.sort((a, b) => b.ovr_estimated - a.ovr_estimated).map((player) => (
                    <div key={player.id} className="flex items-center justify-between p-2 rounded-lg bg-gray-900/50 border border-gray-800 hover:border-gray-700 transition-colors">
                      <div className="w-10 h-10 rounded bg-gray-800 flex items-center justify-center font-black text-xs text-gray-400 border border-gray-700 shrink-0">
                        {player.position || 'N/A'}
                      </div>

                      <div className="flex-1 min-w-0 px-3">
                        <div className="text-sm font-bold text-white truncate">{player.name}</div>
                        <div className="text-[10px] text-gray-500 truncate">
                          {report.fog_level === 'full' && player.traits?.length > 0 ? player.traits.join(', ') : 'No known traits'}
                        </div>
                      </div>

                      <div className="w-16 flex flex-col items-center justify-center shrink-0">
                        <div className="text-lg font-black text-red-500 drop-shadow-[0_0_5px_rgba(239,68,68,0.5)]">
                          {player.ovr_estimated}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
              {report.fog_level !== 'hidden' && (
                <div className="p-3 bg-red-900/10 border-t border-red-900/30 text-[10px] text-red-400/70 text-center font-mono uppercase tracking-widest">
                  WARNING: Stats are estimated based on visual observation.
                </div>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useTransition } from 'react';
import { Activity } from 'lucide-react';
import { logTrainingSession } from '@/app/actions/trainingActions';

export function LogSessionButton({ userId }: { userId: string }) {
  const [isPending, startTransition] = useTransition();
  const [toastMessage, setToastMessage] = useState<{ text: string; type: 'success' | 'error' | 'warning' } | null>(null);

  const handleLogSession = () => {
    startTransition(async () => {
      try {
        // Generate a random duration (30-60 mins) and steps (3000-6000) for testing/simulation
        const duration = Math.floor(Math.random() * 30) + 30;
        const steps = duration * 100 + Math.floor(Math.random() * 500);

        const result = await logTrainingSession(userId, duration, steps);

        if (result.success) {
          if (result.status === 'rejected') {
            setToastMessage({ text: 'Session rejected. Fully exhausted (0% Yield).', type: 'error' });
          } else if (result.status === 'penalized') {
            setToastMessage({ text: `Session penalized. Yield: ${(result.factor * 100).toFixed(0)}% (+${result.earnedTp} TP)`, type: 'warning' });
          } else {
            setToastMessage({ text: `Session approved! Earned: +${result.earnedTp} TP`, type: 'success' });
          }
        } else {
          setToastMessage({ text: result.error || 'Failed to log session.', type: 'error' });
        }
      } catch (error: any) {
        setToastMessage({ text: 'Unexpected error occurred.', type: 'error' });
      } finally {
        // Auto-dismiss toast after 4 seconds
        setTimeout(() => setToastMessage(null), 4000);
      }
    });
  };

  return (
    <>
      {/* Toast Notification */}
      {toastMessage && (
        <div className={`fixed top-4 left-1/2 -translate-x-1/2 z-50 px-4 py-2 rounded-lg shadow-lg font-bold text-sm backdrop-blur-sm animate-in slide-in-from-top-2 border
          ${toastMessage.type === 'error' ? 'bg-red-500/90 border-red-400 text-white' : ''}
          ${toastMessage.type === 'warning' ? 'bg-yellow-500/90 border-yellow-400 text-black' : ''}
          ${toastMessage.type === 'success' ? 'bg-neon-green/90 border-green-400 text-black' : ''}
        `}>
          {toastMessage.text}
        </div>
      )}

      <button 
        onClick={handleLogSession}
        disabled={isPending}
        className={`
          flex items-center justify-center gap-2 w-full sm:w-auto 
          px-6 py-3 rounded-lg font-bold uppercase tracking-widest text-sm
          transition-all shadow-[0_0_15px_rgba(0,240,255,0.3)]
          ${isPending 
            ? 'bg-gray-800 text-gray-500 cursor-not-allowed border border-gray-700' 
            : 'bg-neon-cyan/10 text-neon-cyan border border-neon-cyan hover:bg-neon-cyan hover:text-black hover:shadow-[0_0_20px_rgba(0,240,255,0.6)]'
          }
        `}
      >
        <Activity size={18} className={isPending ? 'animate-pulse' : ''} />
        {isPending ? 'Syncing...' : 'Log Training Session'}
      </button>
    </>
  );
}

'use client';

import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Home, Users, Building2, Droplets, ShoppingCart, Trophy, Lock } from 'lucide-react';
import { useContext } from 'react';
import { LanguageContext } from '@/components/LanguageContext';
import { dict } from '@/lib/dictionaries';
import { useTutorial, TUTORIAL_DONE } from '@/components/providers/TutorialContext';
import toast from 'react-hot-toast';
import { motion } from 'framer-motion';

// ─────────────────────────────────────────────────────────────────────────────
// BottomTabBar — 6-tab navigation with progressive tutorial locking.
//
// Lock rules:
//   tutorial step 0  → all tabs locked except Home
//   tutorial step 1  → lineup unlocked (user must visit squad)
//   tutorial step 2+ → lineup + base unlocked
//   tutorial DONE    → all tabs unlocked
//
// Locked tabs show a 🔒 badge and show a toast on click.
// ─────────────────────────────────────────────────────────────────────────────

const LOCKED_TOAST_MSG = '🎓 Сначала пройди обучение!';

function isTabLocked(href: string, step: number): boolean {
  if (step === TUTORIAL_DONE) return false;
  if (href === '/' || href === '') return false;      // Home always open
  if (href === '/lineup' && step >= 1) return false;  // Unlocked at step 1
  if (href === '/base'   && step >= 2) return false;  // Unlocked at step 2
  return true; // everything else locked during tutorial
}

export function BottomTabBar() {
  const pathname = usePathname();
  const { language } = useContext(LanguageContext);
  const t = dict[language as keyof typeof dict];
  const { step, isDone } = useTutorial();

  const navItems = [
    { name: t.nav_home,   href: '/',        icon: Home,         id: 'tab-home'   },
    { name: t.nav_squad,  href: '/lineup',  icon: Users,        id: 'tab-lineup' },
    { name: 'База',       href: '/base',    icon: Building2,    id: 'tab-base'   },
    { name: 'Банк',       href: '/bank',    icon: Droplets,     id: 'tab-bank'   },
    { name: 'Рынок',      href: '/market',  icon: ShoppingCart, id: 'tab-market' },
    { name: t.nav_league, href: '/league',  icon: Trophy,       id: 'tab-league' },
  ];

  // Hide entirely on onboarding screen
  if (pathname === '/onboarding') return null;

  return (
    <div className="fixed bottom-0 w-full max-w-[480px] z-50
                    bg-gray-950/90 backdrop-blur-xl border-t border-white/5
                    shadow-[0_-4px_30px_rgba(0,0,0,0.5)] pb-safe">

      {/* Active tab glow line */}
      <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r
                      from-transparent via-cyan-500/30 to-transparent" />

      <div className="flex overflow-x-auto scrollbar-none gap-0 px-1 py-2">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          const locked   = isTabLocked(item.href, step);
          const Icon     = item.icon;

          if (locked) {
            return (
              <button
                key={item.href}
                id={item.id}
                aria-label={`${item.name} (locked)`}
                className="flex-shrink-0 flex flex-col items-center justify-center
                           w-[16.666%] min-w-[56px] gap-0.5 relative
                           text-gray-700 active:text-gray-600 transition-colors duration-200"
                onClick={() =>
                  toast(LOCKED_TOAST_MSG, {
                    icon: '🔒',
                    duration: 2000,
                    style: { background: '#111', color: '#fff', border: '1px solid rgba(255,0,60,0.4)' },
                  })
                }
              >
                {/* Lock badge */}
                <div className="relative">
                  <Icon size={22} strokeWidth={1.5} className="opacity-30" />
                  <motion.span
                    className="absolute -top-1.5 -right-1.5 w-3.5 h-3.5 rounded-full
                               bg-red-500/80 flex items-center justify-center
                               shadow-[0_0_6px_rgba(239,68,68,0.6)]"
                    animate={{ scale: [1, 1.15, 1] }}
                    transition={{ repeat: Infinity, duration: 2, ease: 'easeInOut' }}
                  >
                    <Lock size={7} className="text-white" />
                  </motion.span>
                </div>
                <span className="text-[9px] uppercase font-bold tracking-wider opacity-30">
                  {item.name}
                </span>
              </button>
            );
          }

          return (
            <Link
              key={item.href}
              href={item.href}
              id={item.id}
              aria-label={item.name}
              className={`
                flex-shrink-0 flex flex-col items-center justify-center
                w-[16.666%] min-w-[56px] gap-0.5 transition-all duration-200
                active:scale-90
                ${isActive
                  ? 'text-cyan-400 drop-shadow-[0_0_8px_rgba(0,240,255,0.5)]'
                  : 'text-gray-500 hover:text-gray-300'
                }
              `}
            >
              <div className="relative">
                <Icon size={22} strokeWidth={isActive ? 2.5 : 1.8} />
                {isActive && (
                  <motion.span
                    className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1 h-1
                               rounded-full bg-cyan-400 shadow-[0_0_6px_rgba(0,240,255,0.8)]"
                    layoutId="active-dot"
                    transition={{ type: 'spring', stiffness: 380, damping: 30 }}
                  />
                )}
              </div>
              <span className={`text-[9px] uppercase font-bold tracking-wider
                ${isActive ? 'text-cyan-400' : 'text-gray-500'}`}>
                {item.name}
              </span>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

